package com.ethan.combatcalc;

import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Locale;

/**
 * Determines what combat style the player is currently using.
 *
 * ### CombatType (MELEE / RANGED / MAGIC)
 *   Resolved by inspecting the equipped weapon and VarPlayer values:
 *     - If a selected spell is active (varp 108 > 0) → MAGIC.
 *     - If the equipped weapon is in the hardcoded ranged-weapon list → RANGED.
 *     - Otherwise → MELEE.
 *
     *   Powered staves (Trident, Sanguinesti, Tumeken's shadow, etc.) are treated
     *   as MAGIC even when no standard spell is selected.
 *
 * ### AttackSubType (STAB / SLASH / CRUSH / RANGED / MAGIC)
 *   For MELEE, the active attack style VarPlayer is mapped to a sub-type.
 *   Staves always use CRUSH regardless of the style selector.
 *   Unarmed combat (no weapon) defaults to CRUSH.
 *   For RANGED and MAGIC the sub-type is fixed to RANGED or MAGIC respectively.
 */
@Singleton
public class AttackStyleResolver
{
    private final ItemManager itemManager;

    @Inject
    public AttackStyleResolver(ItemManager itemManager)
    {
        this.itemManager = itemManager;
    }

    public AttackStyleType resolve(Client client)
    {
        int style = client.getVarpValue(VarPlayer.ATTACK_STYLE);

        switch (style)
        {
            case 0:
                return AttackStyleType.STAB;
            case 1:
                return AttackStyleType.SLASH;
            case 2:
                return AttackStyleType.CRUSH;
            case 3:
                return AttackStyleType.CONTROLLED;
            default:
                return AttackStyleType.UNKNOWN;
        }
    }

    /**
     * Determines the high-level combat type (MELEE / RANGED / MAGIC).
     *
     * Detection order:
     *   1. If VarPlayer 108 (selected spell) is non-zero → MAGIC.
     *      This covers all standard and ancient spellbook spells.
     *   2. If the equipped weapon is in the ranged-weapon list → RANGED.
     *      Checked regardless of attack style, because some ranged weapons
     *      have a style-3 slot that could be confused with melee controlled stance.
     *   3. Default → MELEE.
     */
    public CombatType resolveCombatType(Client client)
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return CombatType.MELEE;
        }

        // Check for magic spell cast
        int spell = client.getVarpValue(108);
        if (spell > 0)
        {
            return CombatType.MAGIC;
        }

        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        if (weapon != null && weapon.getId() != -1 && PoweredStaffMaxHitResolver.isPoweredStaff(weapon.getId()))
        {
            return CombatType.MAGIC;
        }

        AttackSubType widgetSubType = resolveSubTypeFromCombatOptions(client);
        CombatType widgetCombatType = WeaponAttackStyles.combatTypeFor(widgetSubType);
        if (widgetCombatType != CombatType.UNKNOWN)
        {
            return widgetCombatType;
        }

        // Check attack style - ranged style is 3
        int attackStyle = client.getVarpValue(VarPlayer.ATTACK_STYLE);
        if (attackStyle == 3)
        {
            // This could be ranged defensive stance or controlled
            if (weapon != null && isRangedWeapon(weapon))
            {
                return CombatType.RANGED;
            }
        }

        // Check if weapon is ranged (bow, blowpipe, etc)
        if (weapon != null && weapon.getId() != -1 && isRangedWeapon(weapon))
        {
            return CombatType.RANGED;
        }

        return CombatType.MELEE;
    }

    /**
     * Hardcoded list of ranged weapon item IDs.
     *
     * Used by resolveCombatType() to distinguish ranged weapons from melee weapons.
     * Covers bows, crossbows, the toxic blowpipe, and chinchompas.
     * This list is not exhaustive — newer or uncommon ranged weapons may need to be added.
     */
    private boolean isRangedWeapon(Item weapon)
    {
        String weaponName = getItemName(weapon);
        return weaponName.contains(" bow") ||
                weaponName.endsWith("bow") ||
                weaponName.contains("crossbow") ||
                weaponName.contains("blowpipe") ||
                weaponName.contains("chinchompa") ||
                weaponName.contains(" knife") ||
                weaponName.endsWith("knife") ||
                weaponName.contains(" dart") ||
                weaponName.endsWith("dart") ||
                weaponName.contains("javelin") ||
                weaponName.contains("thrownaxe") ||
                weaponName.contains("thrown axe") ||
                weaponName.contains("ballista");
    }

    /**
     * Hardcoded list of staff/wand item IDs.
     *
     * Staves use the CRUSH attack sub-type in the melee accuracy formula
     * (the weapon uses the crush attack bonus column in the equipment table).
     * This list covers common staves, battlestaves, and magic wands/staffs.
     * It is also used to prevent staves from being misidentified as ranged weapons.
     */
    private boolean isStaff(Item weapon)
    {
        String weaponName = getItemName(weapon);
        return weaponName.contains("staff") ||
                weaponName.contains("battlestaff") ||
                weaponName.contains("trident") ||
                weaponName.contains("wand") ||
                weaponName.contains("sceptre") ||
                weaponName.contains("scepter") ||
                weaponName.contains("crozier");
    }

    /**
     * Resolves attack subtype based on combat type and style.
     */
    public AttackSubType resolveAttackSubType(Client client, CombatType combatType)
    {
        switch (combatType)
        {
            case MELEE:
                return resolveMeleeSubType(client);
            case RANGED:
                return AttackSubType.RANGED;
            case MAGIC:
                return AttackSubType.MAGIC;
            default:
                return AttackSubType.UNKNOWN;
        }
    }

    /**
     * Maps the active VarPlayer attack-style index to an AttackSubType for melee.
     *
     * VarPlayer.ATTACK_STYLE values for a typical weapon:
     *   0 → Stab (Accurate)
     *   1 → Slash (Aggressive)
     *   2 → Crush (Defensive)
     *   3 → Stab  (Controlled — maps to stab as the closest equivalent)
     *
     * The exact mapping varies by weapon type; this covers the common sword/dagger layout.
     * Staves always return CRUSH before this switch is reached.
     */
    private AttackSubType resolveMeleeSubType(Client client)
    {
        AttackSubType widgetSubType = resolveSubTypeFromCombatOptions(client);
        if (widgetSubType != AttackSubType.UNKNOWN)
        {
            return widgetSubType;
        }

        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        Item weapon = equipment != null ? equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx()) : null;

        // Unarmed combat always uses crush
        if (weapon == null || weapon.getId() == -1)
        {
            return AttackSubType.CRUSH;
        }

        // Staves always use crush attack style
        if (isStaff(weapon))
        {
            return AttackSubType.CRUSH;
        }

        int style = client.getVarpValue(VarPlayer.ATTACK_STYLE);

        switch (style)
        {
            case 0:
                return AttackSubType.STAB;
            case 1:
                return AttackSubType.SLASH;
            case 2:
                return AttackSubType.CRUSH;
            case 3:
                return AttackSubType.STAB;
            default:
                return AttackSubType.UNKNOWN;
        }
    }

    private AttackSubType resolveSubTypeFromCombatOptions(Client client)
    {
        Widget categoryWidget = client.getWidget(InterfaceID.CombatInterface.CATEGORY);
        if (categoryWidget == null)
        {
            return AttackSubType.UNKNOWN;
        }

        return WeaponAttackStyles.resolveAttackSubType(categoryWidget.getText(), client.getVarpValue(VarPlayer.ATTACK_STYLE));
    }

    private String getItemName(Item weapon)
    {
        if (weapon == null || weapon.getId() == -1 || itemManager == null)
        {
            return "";
        }

        String name = itemManager.getItemComposition(weapon.getId()).getName();
        if (name == null)
        {
            return "";
        }

        return name.toLowerCase(Locale.ROOT);
    }
}

package com.ethan.combatcalc;

public enum AttackStyleType
{
    STAB("Stab"),
    SLASH("Slash"),
    CRUSH("Crush"),
    CONTROLLED("Controlled"),
    UNKNOWN("Unknown");

    private final String displayName;

    AttackStyleType(String displayName)
    {
        this.displayName = displayName;
    }

    public String getDisplayName()
    {
        return displayName;
    }
}

package com.ethan.combatcalc;

public enum AttackSubType
{
    // Melee subtypes
    STAB("Stab"),
    SLASH("Slash"),
    CRUSH("Crush"),
    // Ranged subtypes
    RANGED("Ranged"),
    // Magic subtypes
    MAGIC("Magic"),
    // Fallback
    UNKNOWN("Unknown");

    private final String displayName;

    AttackSubType(String displayName)
    {
        this.displayName = displayName;
    }

    public String getDisplayName()
    {
        return displayName;
    }
}

package com.ethan.combatcalc;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Core combat accuracy and max-hit calculation engine.
 *
 * All formulas implement the standard OSRS mechanics documented on the OSRS wiki:
 *   https://oldschool.runescape.wiki/w/Combat
 *
 * ### How OSRS accuracy works (all three styles)
 *
 *   1. Compute an OFFENSIVE ROLL: effectiveLevel * (equipmentBonus + 64)
 *      where effectiveLevel includes prayer, stance bonus, and the +8 baseline.
 *
 *   2. Compute a DEFENSIVE ROLL for the NPC: (npcDefenceLevel + 9) * (defenceBonus + 64)
 *      For magic, the NPC’s magic level is used instead of its defence level.
 *
 *   3. Apply any special multipliers (prayers, Salve, Slayer helm, etc.) via CombatModifier.
 *
 *   4. Feed both rolls into calculateHitChance() to get a value in [0.0, 1.0].
 *
 * ### Max hit
 *   Melee and ranged max hits are calculated here.
 *   Magic max hit uses a spell or powered-staff base max hit supplied by the caller.
 */
@Singleton
public class CombatCalculator
{
    private static final double ACCURACY_THRESHOLD = 2.0;
    private final CombatModifier combatModifier;

    @Inject
    public CombatCalculator(CombatModifier combatModifier)
    {
        this.combatModifier = combatModifier;
    }

    /**
     * Calculates melee hit chance and max hit.
     *
     * Offensive roll = effectiveAttackLevel * (attackBonus + 64)
     *   where attackBonus is the equipment bonus for the active sub-type
     *   (stab / slash / crush), chosen by the AttackStyleResolver.
     *
     * Defensive roll = (npcDefenceLevel + 9) * (npcDefenceBonusForSubType + 64)
     *   The NPC defence bonus used is the one matching the player’s attack sub-type,
     *   e.g. stab attack reads the NPC’s stab defence stat.
     *
     * The offensive roll is multiplied by any active modifiers (prayers, Salve, etc.)
     * before being compared to the defensive roll.
     *
     * Max hit uses the melee strength formula (see calculateMeleeMaxHit).
     */
    public CombatResult calculateMeleeAccuracy(CombatProfile playerProfile, NpcCombatProfile npcProfile)
    {
        CombatResult result = new CombatResult();
        result.setCombatType(CombatType.MELEE);
        result.setAttackSubType(playerProfile.getAttackSubType());

        int effectiveAttackLevel = calculateEffectiveLevel(
                playerProfile.getEffectiveAttackLevel(),
                combatModifier.getAccuracyPrayerMultiplier(CombatType.MELEE),
                playerProfile.getAccuracyStyleBonus());
        int offensiveRoll = effectiveAttackLevel * (playerProfile.getAttackBonus() + 64);

        // Apply special modifiers
        double modifier = combatModifier.getOffensiveRollMultiplier(CombatType.MELEE, npcProfile);
        int modifiedOffensiveRoll = (int) (offensiveRoll * modifier);

        result.setOffensiveRoll(modifiedOffensiveRoll);

        int defenceBonus = npcProfile.getDefenceBonusForAttackType(playerProfile.getAttackSubType());
        int defensiveRoll = calculateNpcDefensiveRoll(npcProfile.getDefenceLevel(), defenceBonus);
        result.setDefensiveRoll(defensiveRoll);

        // Calculate hit chance
        double hitChance = calculateHitChance(modifiedOffensiveRoll, defensiveRoll);
        result.setHitChance(hitChance);

        // Calculate max hit
        int maxHit = calculateMeleeMaxHit(
                playerProfile.getEffectiveStrengthLevel(),
                playerProfile.getStrengthBonus(),
                playerProfile.getStrengthStyleBonus(),
                combatModifier.getStrengthPrayerMultiplier(),
                combatModifier.getDamageMultiplier(CombatType.MELEE, npcProfile));
        result.setMaxHit(maxHit);

        return result;
    }

    /**
     * Calculates ranged hit chance and max hit.
     *
     * Offensive roll = effectiveRangedLevel * (rangedAttackBonus + 64)
     * Defensive roll = (npcDefenceLevel + 9) * (npcRangedDefence + 64)
     *
     * Max hit uses the ranged strength formula (see calculateRangedMaxHit).
     */
    public CombatResult calculateRangedAccuracy(CombatProfile playerProfile, NpcCombatProfile npcProfile)
    {
        CombatResult result = new CombatResult();
        result.setCombatType(CombatType.RANGED);
        result.setAttackSubType(AttackSubType.RANGED);

        int effectiveRangedLevel = calculateEffectiveLevel(
                playerProfile.getEffectiveAttackLevel(),
                combatModifier.getAccuracyPrayerMultiplier(CombatType.RANGED),
                playerProfile.getAccuracyStyleBonus());
        int offensiveRoll = effectiveRangedLevel * (playerProfile.getAttackBonus() + 64);

        // Apply special modifiers
        double modifier = combatModifier.getOffensiveRollMultiplier(CombatType.RANGED, npcProfile);
        int modifiedOffensiveRoll = (int) (offensiveRoll * modifier);

        result.setOffensiveRoll(modifiedOffensiveRoll);

        int defensiveRoll = calculateNpcDefensiveRoll(npcProfile.getDefenceLevel(), npcProfile.getRangedDefence());
        result.setDefensiveRoll(defensiveRoll);

        // Calculate hit chance
        double hitChance = calculateHitChance(modifiedOffensiveRoll, defensiveRoll);
        result.setHitChance(hitChance);

        // Calculate max hit
        int maxHit = calculateRangedMaxHit(
            playerProfile.getEffectiveStrengthLevel(),
                playerProfile.getRangedStrengthBonus(),
                playerProfile.getRangedStrengthStyleBonus(),
                combatModifier.getRangedStrengthPrayerMultiplier(),
                combatModifier.getDamageMultiplier(CombatType.RANGED, npcProfile));
        result.setMaxHit(maxHit);

        return result;
    }

    /**
     * Calculates magic hit chance (PvM only).
     *
     * Offensive roll = effectiveMagicLevel * (magicAttackBonus + 64)
     *
     * PvM defensive roll uses the NPC’s MAGIC LEVEL (not defence level) as the
     * base stat, combined with the NPC’s magic defence bonus:
     *   Defensive roll = (npcMagicLevel + 9) * (npcMagicDefence + 64)
     *
     * Magic max hit is spell-dependent and uses the caller-provided base max hit.
     */
    public CombatResult calculateMagicAccuracy(CombatProfile playerProfile, NpcCombatProfile npcProfile)
    {
        CombatResult result = new CombatResult();
        result.setCombatType(CombatType.MAGIC);
        result.setAttackSubType(AttackSubType.MAGIC);

        int effectiveMagicLevel = calculateEffectiveLevel(
                playerProfile.getEffectiveAttackLevel(),
                combatModifier.getAccuracyPrayerMultiplier(CombatType.MAGIC),
                playerProfile.getAccuracyStyleBonus());
        int offensiveRoll = effectiveMagicLevel * (playerProfile.getAttackBonus() + 64);

        // Apply special modifiers
        double modifier = combatModifier.getOffensiveRollMultiplier(CombatType.MAGIC, npcProfile);
        int modifiedOffensiveRoll = (int) (offensiveRoll * modifier);

        result.setOffensiveRoll(modifiedOffensiveRoll);

        int defensiveRoll = calculateNpcDefensiveRoll(npcProfile.getMagicLevel(), npcProfile.getMagicDefence());
        result.setDefensiveRoll(defensiveRoll);

        // Calculate hit chance
        double hitChance = calculateHitChance(modifiedOffensiveRoll, defensiveRoll);
        result.setHitChance(hitChance);

        int maxHit = calculateMagicMaxHit(
                playerProfile.getMaxHitBase(),
                playerProfile.getMagicDamageBonus(),
                combatModifier.getDamageMultiplier(CombatType.MAGIC, npcProfile),
                getElementalWeaknessBonus(playerProfile, npcProfile));
        result.setMaxHit(maxHit);

        return result;
    }

    /**
     * The standard OSRS two-branch hit-chance formula.
     *
     * When attack > defence (strong attacker):
     *   hitChance = 1 - (defenceRoll + 2) / (2 * (attackRoll + 1))
     *
     * When attack <= defence (weak attacker or equal):
     *   hitChance = attackRoll / (2 * (defenceRoll + 1))
     *
     * The result is clamped to [0.0, 1.0] as a safety measure, though the
     * formulas naturally stay within range for non-negative inputs.
     *
     * Source: https://oldschool.runescape.wiki/w/Accuracy
     */
    private double calculateHitChance(int offensiveRoll, int defensiveRoll)
    {
        double hitChance;

        if (offensiveRoll > defensiveRoll)
        {
            // If attack roll > defence roll:  1 - (defence roll + 2) / (2 * (attack roll + 1))
            hitChance = 1.0 - (double) (defensiveRoll + 2) / (2.0 * (offensiveRoll + 1));
        }
        else
        {
            // If attack roll <= defence roll:  attack roll / (2 * (defence roll + 1))
            hitChance = (double) offensiveRoll / (2.0 * (defensiveRoll + 1));
        }

        // Clamp to valid hit chance range [0.0, 1.0]
        return Math.max(0.0, Math.min(1.0, hitChance));
    }

    /**
     * Melee max hit formula.
     *
     * Simplified form of the OSRS wiki formula:
     *   maxHit = floor( (strengthLevel + 1) * ((strengthBonus / 8) + 1) )
     *
     * strengthLevel  — the player’s effective strength level (boosted).
     * strengthBonus  — the total melee strength bonus summed from all equipped gear.
     */
    public int calculateMeleeMaxHit(int strengthLevel, int strengthBonus)
    {
        return calculateMeleeMaxHit(strengthLevel, strengthBonus, 0, 1.0, 1.0);
    }

    public int calculateMeleeMaxHit(int strengthLevel, int strengthBonus, double prayerMultiplier, double damageMultiplier)
    {
        return calculateMeleeMaxHit(strengthLevel, strengthBonus, 0, prayerMultiplier, damageMultiplier);
    }

    public int calculateMeleeMaxHit(int strengthLevel, int strengthBonus, int styleBonus, double prayerMultiplier, double damageMultiplier)
    {
        int effectiveStrength = calculateEffectiveLevel(strengthLevel, prayerMultiplier, styleBonus);
        int baseMaxHit = (int) Math.floor(0.5 + effectiveStrength * (strengthBonus + 64) / 640.0);
        return (int) Math.floor(baseMaxHit * damageMultiplier);
    }

    /**
     * Ranged max hit formula.
     *
    *   maxHit = floor( 0.5 + rangedLevel * (rangedStrengthBonus + 64) / 640 )
     *
     * rangedLevel          — effective ranged level (boosted).
     * rangedStrengthBonus  — the ranged strength bonus from equipped ammunition/weapon.
     */
    public int calculateRangedMaxHit(int rangedLevel, int rangedStrengthBonus)
    {
        return calculateRangedMaxHit(rangedLevel, rangedStrengthBonus, 0, 1.0, 1.0);
    }

    public int calculateRangedMaxHit(int rangedLevel, int rangedStrengthBonus, double prayerMultiplier, double damageMultiplier)
    {
        return calculateRangedMaxHit(rangedLevel, rangedStrengthBonus, 0, prayerMultiplier, damageMultiplier);
    }

    public int calculateRangedMaxHit(int rangedLevel, int rangedStrengthBonus, int styleBonus, double prayerMultiplier, double damageMultiplier)
    {
        int effectiveRangedStrength = calculateEffectiveLevel(rangedLevel, prayerMultiplier, styleBonus);
        int baseMaxHit = (int) Math.floor(0.5 + effectiveRangedStrength * (rangedStrengthBonus + 64) / 640.0);
        return (int) Math.floor(baseMaxHit * damageMultiplier);
    }

    public int calculateMagicMaxHit(int baseMaxHit, int magicDamageBonus, double damageMultiplier)
    {
        return calculateMagicMaxHit(baseMaxHit, magicDamageBonus, damageMultiplier, 0);
    }

    public int calculateMagicMaxHit(int baseMaxHit, int magicDamageBonus, double damageMultiplier, int elementalWeaknessPercent)
    {
        if (baseMaxHit <= 0)
        {
            return 0;
        }

        double gearMultiplier = 1.0 + (magicDamageBonus / 100.0);
        int boostedHit = (int) Math.floor(baseMaxHit * gearMultiplier * damageMultiplier);
        int elementalBonus = (int) Math.floor(baseMaxHit * elementalWeaknessPercent / 100.0);
        return boostedHit + elementalBonus;
    }

    private int getElementalWeaknessBonus(CombatProfile playerProfile, NpcCombatProfile npcProfile)
    {
        if (playerProfile.getSpellElement() == null || npcProfile.getWikiWeakness() == null)
        {
            return 0;
        }

        if (!playerProfile.getSpellElement().equalsIgnoreCase(npcProfile.getWikiWeakness()))
        {
            return 0;
        }

        return Math.max(0, npcProfile.getElementalWeaknessPercent());
    }

    private int calculateEffectiveLevel(int boostedLevel, double prayerMultiplier)
    {
        return calculateEffectiveLevel(boostedLevel, prayerMultiplier, 0);
    }

    private int calculateEffectiveLevel(int boostedLevel, double prayerMultiplier, int styleBonus)
    {
        return (int) Math.floor(boostedLevel * prayerMultiplier) + styleBonus + 8;
    }

    private int calculateNpcDefensiveRoll(int npcLevel, int defenceBonus)
    {
        return (npcLevel + 9) * (defenceBonus + 64);
    }
}

package com.ethan.combatcalc;

import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemID;
import net.runelite.api.ItemContainer;
import net.runelite.api.Prayer;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Locale;

/**
 * Computes special accuracy multipliers that sit on top of the base offensive roll.
 *
 * ### Multipliers applied (stacked multiplicatively)
 *
 *   Salve amulet     — +15% accuracy vs undead NPCs (name-based detection).
 *   Slayer helmet    — +15% accuracy when on a Slayer task (task detection is a TODO;
 *                       currently returns false so no bonus is applied).
 *   Prayer           — varies by prayer and combat type (see getPrayerAccuracyMultiplier).
 *
 * All equipment checks read the live ItemContainer for the EQUIPMENT inventory —
 * no state is cached between ticks.
 */
@Singleton
public class CombatModifier
{
    private final Client client;
    private final WillItLandConfig config;
    private final EquipmentSynergyDetector equipmentSynergyDetector;
    private final SlayerTaskProvider slayerTaskProvider;
    private final ItemManager itemManager;

    @Inject
    public CombatModifier(Client client,
                          WillItLandConfig config,
                          EquipmentSynergyDetector equipmentSynergyDetector,
                          SlayerTaskProvider slayerTaskProvider,
                          ItemManager itemManager)
    {
        this.client = client;
        this.config = config;
        this.equipmentSynergyDetector = equipmentSynergyDetector;
        this.slayerTaskProvider = slayerTaskProvider;
        this.itemManager = itemManager;
    }

    public CombatModifier(Client client,
                          WillItLandConfig config,
                          EquipmentSynergyDetector equipmentSynergyDetector,
                          SlayerTaskProvider slayerTaskProvider)
    {
        this(client, config, equipmentSynergyDetector, slayerTaskProvider, null);
    }

    public CombatModifier(Client client, WillItLandConfig config, EquipmentSynergyDetector equipmentSynergyDetector)
    {
        this(client, config, equipmentSynergyDetector, new RuneLiteSlayerTaskProvider(client), null);
    }

    public CombatModifier(Client client)
    {
        this(client, null, null, new RuneLiteSlayerTaskProvider(client), null);
    }

    /**
     * Returns the combined accuracy multiplier for all active bonuses.
     *
     * Multipliers are applied in sequence (not averaged) to match how OSRS
     * stacks bonuses in the base engine.
     *
     * @param combatType  The current combat style (used to pick the right prayer tier).
     * @param npcProfile  The target NPC (used for Salve undead check and future Slayer task check).
     * @return            A multiplier ≥ 1.0 to scale the offensive roll by.
     */
    public double getOffensiveRollMultiplier(CombatType combatType, NpcCombatProfile npcProfile)
    {
        double multiplier = 1.0;

        if (specialModifiersEnabled())
        {
            multiplier *= getBestTargetSpecificMultiplier(combatType, npcProfile);
        }

        if (equipmentSetsEnabled() && equipmentSynergyDetector != null)
        {
            multiplier *= equipmentSynergyDetector.getSetEffectAccuracyMultiplier(combatType);
        }

        return multiplier;
    }

    public double getDamageMultiplier(CombatType combatType, NpcCombatProfile npcProfile)
    {
        double multiplier = 1.0;

        if (specialModifiersEnabled())
        {
            multiplier *= getBestTargetSpecificMultiplier(combatType, npcProfile);
        }

        if (equipmentSetsEnabled() && equipmentSynergyDetector != null)
        {
            multiplier *= equipmentSynergyDetector.getSetEffectDamageMultiplier(combatType);
        }

        return multiplier;
    }

    public double getAccuracyPrayerMultiplier(CombatType combatType)
    {
        if (!prayerBonusesEnabled())
        {
            return 1.0;
        }

        return getPrayerAccuracyMultiplier(combatType);
    }

    public double getStrengthPrayerMultiplier()
    {
        if (client == null || !prayerBonusesEnabled())
        {
            return 1.0;
        }

        if (client.isPrayerActive(Prayer.PIETY))
        {
            return 1.23;
        }
        if (client.isPrayerActive(Prayer.CHIVALRY))
        {
            return 1.18;
        }
        if (client.isPrayerActive(Prayer.ULTIMATE_STRENGTH))
        {
            return 1.15;
        }
        if (client.isPrayerActive(Prayer.SUPERHUMAN_STRENGTH))
        {
            return 1.10;
        }
        if (client.isPrayerActive(Prayer.BURST_OF_STRENGTH))
        {
            return 1.05;
        }

        return 1.0;
    }

    public double getRangedStrengthPrayerMultiplier()
    {
        if (client == null || !prayerBonusesEnabled())
        {
            return 1.0;
        }

        if (client.isPrayerActive(Prayer.RIGOUR))
        {
            return 1.23;
        }
        if (client.isPrayerActive(Prayer.EAGLE_EYE))
        {
            return 1.15;
        }
        if (client.isPrayerActive(Prayer.HAWK_EYE))
        {
            return 1.10;
        }
        if (client.isPrayerActive(Prayer.SHARP_EYE))
        {
            return 1.05;
        }

        return 1.0;
    }

    private boolean prayerBonusesEnabled()
    {
        return config == null || config.enablePrayerBonuses();
    }

    private boolean specialModifiersEnabled()
    {
        return config == null || config.enableSpecialModifiers();
    }

    private boolean equipmentSetsEnabled()
    {
        return config == null || config.enableEquipmentSets();
    }

    /**
     * Returns the prayer accuracy multiplier for the active prayer in the given combat style.
     *
     * Only the highest applicable prayer is returned (the player can only have one
     * accuracy prayer active at a time in OSRS).
     *
     * Melee:  Clarity of Thought +5%, Improved Reflexes +10%,
     *         Incredible Reflexes / Chivalry +15%, Piety +20%.
     * Ranged: Sharp Eye +5%, Hawk Eye +10%, Eagle Eye +15%, Rigour +20%.
     * Magic:  Mystic Will +5%, Mystic Lore +10%, Mystic Might +15%, Augury +25%.
     */
    private double getPrayerAccuracyMultiplier(CombatType combatType)
    {
        if (client == null)
        {
            return 1.0;
        }

        switch (combatType)
        {
            case MELEE:
                if (client.isPrayerActive(Prayer.PIETY))
                {
                    return 1.20; // 20% boost
                }
                if (client.isPrayerActive(Prayer.CHIVALRY))
                {
                    return 1.15; // 15% boost
                }
                if (client.isPrayerActive(Prayer.INCREDIBLE_REFLEXES))
                {
                    return 1.15; // 15% boost
                }
                if (client.isPrayerActive(Prayer.IMPROVED_REFLEXES))
                {
                    return 1.10; // 10% boost
                }
                if (client.isPrayerActive(Prayer.CLARITY_OF_THOUGHT))
                {
                    return 1.05; // 5% boost
                }
                break;

            case RANGED:
                if (client.isPrayerActive(Prayer.RIGOUR))
                {
                    return 1.20; // 20% boost
                }
                if (client.isPrayerActive(Prayer.EAGLE_EYE))
                {
                    return 1.15; // 15% boost
                }
                if (client.isPrayerActive(Prayer.HAWK_EYE))
                {
                    return 1.10; // 10% boost
                }
                if (client.isPrayerActive(Prayer.SHARP_EYE))
                {
                    return 1.05; // 5% boost
                }
                break;

            case MAGIC:
                if (client.isPrayerActive(Prayer.AUGURY))
                {
                    return 1.25; // 25% boost
                }
                if (client.isPrayerActive(Prayer.MYSTIC_MIGHT))
                {
                    return 1.15; // 15% boost
                }
                if (client.isPrayerActive(Prayer.MYSTIC_LORE))
                {
                    return 1.10; // 10% boost
                }
                if (client.isPrayerActive(Prayer.MYSTIC_WILL))
                {
                    return 1.05; // 5% boost
                }
                break;
        }

        return 1.0;
    }

    /**
     * Checks if the player is wearing a Salve amulet.
     */
    private boolean wearingSalveAmulet()
    {
        String amuletName = normalizeName(getEquippedItemName(EquipmentInventorySlot.AMULET));
        if (amuletName.contains("salve amulet"))
        {
            return true;
        }

        int amuletId = getEquippedAmuletId();
        return amuletId == ItemID.SALVE_AMULET ||
                amuletId == ItemID.SALVE_AMULET_E ||
                amuletId == ItemID.SALVE_AMULETI ||
                amuletId == ItemID.SALVE_AMULETEI ||
                amuletId == ItemID.SALVE_AMULETI_25250 ||
                amuletId == ItemID.SALVE_AMULETEI_25278 ||
                amuletId == ItemID.SALVE_AMULETI_26763 ||
                amuletId == ItemID.SALVE_AMULETEI_26782;
    }

    private boolean isSalveAccuracyApplicable(CombatType combatType, NpcCombatProfile npcProfile)
    {
        return wearingSalveAmulet() && isUndeadNPC(npcProfile) && getSalveMultiplier(combatType) > 1.0;
    }

    private double getBestTargetSpecificMultiplier(CombatType combatType, NpcCombatProfile npcProfile)
    {
        if (isSalveAccuracyApplicable(combatType, npcProfile))
        {
            return getSalveMultiplier(combatType);
        }

        return slayerHelmetApplies(combatType, npcProfile) ? getSlayerHelmMultiplier(combatType) : 1.0;
    }

    private double getSalveMultiplier(CombatType combatType)
    {
        String amuletName = normalizeName(getEquippedItemName(EquipmentInventorySlot.AMULET));
        int amuletId = getEquippedAmuletId();
        if (amuletId == -1 && amuletName.isEmpty())
        {
            return 1.0;
        }

        boolean enchanted = amuletName.contains("salve amulet(e)") ||
                amuletName.contains("salve amulet(ei)") ||
                amuletId == ItemID.SALVE_AMULET_E ||
                amuletId == ItemID.SALVE_AMULETEI ||
                amuletId == ItemID.SALVE_AMULETEI_25278 ||
                amuletId == ItemID.SALVE_AMULETEI_26782;
        boolean imbued = amuletName.contains("salve amulet(i)") ||
                amuletName.contains("salve amulet(ei)") ||
                amuletId == ItemID.SALVE_AMULETI ||
                amuletId == ItemID.SALVE_AMULETEI ||
                amuletId == ItemID.SALVE_AMULETI_25250 ||
                amuletId == ItemID.SALVE_AMULETEI_25278 ||
                amuletId == ItemID.SALVE_AMULETI_26763 ||
                amuletId == ItemID.SALVE_AMULETEI_26782;

        if (combatType == CombatType.MELEE)
        {
            return enchanted ? 1.20 : 1.15;
        }

        if (!imbued)
        {
            return 1.0;
        }

        if (combatType == CombatType.MAGIC)
        {
            return enchanted ? 1.20 : 1.15;
        }

        if (combatType == CombatType.RANGED)
        {
            return enchanted ? 1.20 : (7.0 / 6.0);
        }

        return 1.0;
    }

    private double getSlayerHelmMultiplier(CombatType combatType)
    {
        return combatType == CombatType.MELEE ? (7.0 / 6.0) : 1.15;
    }

    private int getEquippedAmuletId()
    {
        ItemContainer equipment = client != null ? client.getItemContainer(InventoryID.EQUIPMENT) : null;
        if (equipment == null)
        {
            return -1;
        }

        Item amulet = equipment.getItem(EquipmentInventorySlot.AMULET.getSlotIdx());
        return amulet == null ? -1 : amulet.getId();
    }

    /**
     * Checks if the player is wearing a Slayer helmet.
     */
    private boolean wearingSlayerHelm()
    {
        String headName = normalizeName(getEquippedItemName(EquipmentInventorySlot.HEAD));
        if (headName.contains("slayer helmet") || headName.equals("black mask"))
        {
            return true;
        }

        if (client == null)
        {
            return false;
        }

        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return false;
        }

        Item head = equipment.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
        if (head == null || head.getId() == -1)
        {
            return false;
        }

        int headId = head.getId();
        return headId == ItemID.SLAYER_HELMET ||
                headId == ItemID.BLACK_SLAYER_HELMET ||
                headId == ItemID.GREEN_SLAYER_HELMET ||
                headId == ItemID.RED_SLAYER_HELMET ||
                headId == ItemID.PURPLE_SLAYER_HELMET ||
                headId == ItemID.TURQUOISE_SLAYER_HELMET ||
                headId == ItemID.HYDRA_SLAYER_HELMET ||
                headId == ItemID.TWISTED_SLAYER_HELMET ||
                headId == ItemID.TZTOK_SLAYER_HELMET ||
                headId == ItemID.TZKAL_SLAYER_HELMET ||
                headId == ItemID.VAMPYRIC_SLAYER_HELMET ||
                headId == ItemID.ARAXYTE_SLAYER_HELMET ||
                headId == ItemID.HOODED_SLAYER_HELMET ||
                wearingImbueSlayerHelm();
    }

    /**
     * Checks if the player is wearing an Imbued Slayer helmet.
     */
    private boolean wearingImbueSlayerHelm()
    {
        String headName = normalizeName(getEquippedItemName(EquipmentInventorySlot.HEAD));
        if (headName.contains("slayer helmet i") || headName.contains("black mask i"))
        {
            return true;
        }

        if (client == null)
        {
            return false;
        }

        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return false;
        }

        Item head = equipment.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
        if (head == null || head.getId() == -1)
        {
            return false;
        }

        int headId = head.getId();
        return headId == ItemID.SLAYER_HELMET_I ||
                headId == ItemID.BLACK_SLAYER_HELMET_I ||
                headId == ItemID.GREEN_SLAYER_HELMET_I ||
                headId == ItemID.RED_SLAYER_HELMET_I ||
                headId == ItemID.PURPLE_SLAYER_HELMET_I ||
                headId == ItemID.TURQUOISE_SLAYER_HELMET_I ||
                headId == ItemID.HYDRA_SLAYER_HELMET_I ||
                headId == ItemID.TWISTED_SLAYER_HELMET_I ||
                headId == ItemID.TZTOK_SLAYER_HELMET_I ||
                headId == ItemID.TZKAL_SLAYER_HELMET_I ||
                headId == ItemID.VAMPYRIC_SLAYER_HELMET_I ||
                headId == ItemID.ARAXYTE_SLAYER_HELMET_I ||
                headId == ItemID.HOODED_SLAYER_HELMET_I;
    }

    /**
     * Undead detection for the Salve amulet bonus.
     *
     * Uses a simple name-substring match against known undead keywords.
     * This avoids needing an NPC ID list and covers variants (e.g. "Barrows brother").
     * The check is case-insensitive.
     */
    private boolean isUndeadNPC(NpcCombatProfile npcProfile)
    {
        if (npcProfile == null || npcProfile.getNpcName() == null)
        {
            return false;
        }

        String name = npcProfile.getNpcName().toLowerCase();
        return name.contains("zombie") ||
                name.contains("skeleton") ||
                name.contains("ghost") ||
                name.contains("spectre") ||
                name.contains("shade") ||
                name.contains("ghoul") ||
                name.contains("mummy") ||
            name.contains("revenant") ||
            name.contains("ankou") ||
            name.contains("zogre") ||
                name.contains("barrows") ||
                name.contains("undead") ||
                name.contains("wight");
    }

    /**
     * Slayer task detection uses RuneLite's slayer varps/DB rows via SlayerTaskProvider.
     */
    private boolean isOnSlayerTask(NpcCombatProfile npcProfile)
    {
        if (npcProfile == null || npcProfile.getNpcName() == null || slayerTaskProvider == null)
        {
            return false;
        }

        return taskMatchesNpc(slayerTaskProvider.getTaskName(), npcProfile.getNpcName());
    }

    private boolean slayerHelmetApplies(CombatType combatType, NpcCombatProfile npcProfile)
    {
        if (!isOnSlayerTask(npcProfile))
        {
            return false;
        }

        if (combatType == CombatType.MELEE)
        {
            return wearingSlayerHelm();
        }

        return wearingImbueSlayerHelm() && (combatType == CombatType.RANGED || combatType == CombatType.MAGIC);
    }

    private boolean taskMatchesNpc(String taskName, String npcName)
    {
        String task = normalizeTaskName(taskName);
        String npc = normalizeName(npcName);
        if (task.isEmpty() || npc.isEmpty())
        {
            return false;
        }

        return task.contains(npc) || npc.contains(task);
    }

    private String normalizeTaskName(String taskName)
    {
        String task = normalizeName(taskName);
        if (task.endsWith("ies"))
        {
            return task.substring(0, task.length() - 3) + "y";
        }
        if (task.endsWith("s"))
        {
            return task.substring(0, task.length() - 1);
        }
        return task;
    }

    private String normalizeName(String name)
    {
        if (name == null)
        {
            return "";
        }

        return name.toLowerCase(Locale.ROOT)
                .replaceAll("[^a-z0-9 ]", " ")
                .replaceAll("\\s+", " ")
                .trim();
    }

    private String getEquippedItemName(EquipmentInventorySlot slot)
    {
        if (itemManager == null || client == null)
        {
            return "";
        }

        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return "";
        }

        Item item = equipment.getItem(slot.getSlotIdx());
        if (item == null || item.getId() == -1)
        {
            return "";
        }

        try
        {
            net.runelite.api.ItemComposition composition = itemManager.getItemComposition(item.getId());
            return composition != null && composition.getName() != null ? composition.getName() : "";
        }
        catch (RuntimeException ex)
        {
            return "";
        }
    }
}

