package com.ethan.combatcalc;
import net.runelite.api.InventoryID;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemStats;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Sums all offensive and defensive equipment bonuses from the player’s worn gear.
 *
 * ### How it works
 *   On each call to collectBonuses(), the EQUIPMENT ItemContainer is read and every
 *   occupied slot is iterated.  For each item, ItemManager.getItemStats() is called to
 *   retrieve the cached ItemEquipmentStats, which exposes the same bonus columns shown
 *   on the in-game equipment screen (stab, slash, crush, magic, ranged attack;
 *   strength, ranged strength; all defence bonuses).
 *
 *   All values are summed into a plain EquipmentBonuses data object and returned.
 *
 * ### No caching
 *   Stats are re-read fresh on every call.  This keeps the code simple and ensures
 *   the values are always up to date without needing to listen to inventory change events.
 *
 * ### No file I/O or network calls
 *   ItemManager serves stats from RuneLite’s local item cache — no external requests.
 */
@Singleton
public class EquipmentStatCollector
{
    private final Client client;
    private final ItemManager itemManager;

    @Inject
    public EquipmentStatCollector(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;
    }

    /**
     * Collects all equipment bonuses from worn gear.
     */
    public EquipmentBonuses collectBonuses()
    {
        EquipmentBonuses bonuses = new EquipmentBonuses();

        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return bonuses;
        }

        // Iterate through all equipment slots
        for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
        {
            Item item = equipment.getItem(slot.getSlotIdx());
            if (item == null || item.getId() == -1)
            {
                continue;
            }

            ItemStats itemStats = itemManager.getItemStats(item.getId());
            if (itemStats == null)
            {
                continue;
            }

            ItemEquipmentStats equipStats = itemStats.getEquipment();
            if (equipStats == null)
            {
                continue;
            }

            // Sum up attack bonuses
            bonuses.stabAttack += equipStats.getAstab();
            bonuses.slashAttack += equipStats.getAslash();
            bonuses.crushAttack += equipStats.getAcrush();
            bonuses.magicAttack += equipStats.getAmagic();
            bonuses.rangedAttack += equipStats.getArange();

            // Sum up strength bonuses
            bonuses.strengthBonus += equipStats.getStr();
            bonuses.rangedStrengthBonus += equipStats.getRstr();
            bonuses.magicDamageBonus += equipStats.getMdmg();

            // Defence bonuses
            bonuses.stabDefence += equipStats.getDstab();
            bonuses.slashDefence += equipStats.getDslash();
            bonuses.crushDefence += equipStats.getDcrush();
            bonuses.rangedDefence += equipStats.getDrange();
            bonuses.magicDefence += equipStats.getDmagic();
        }

        return bonuses;
    }

    /**
     * Container class for equipment bonuses.
     */
    public static class EquipmentBonuses
    {
        public int stabAttack = 0;
        public int slashAttack = 0;
        public int crushAttack = 0;
        public int magicAttack = 0;
        public int rangedAttack = 0;
        public int strengthBonus = 0;
        public int rangedStrengthBonus = 0;
        public int magicDamageBonus = 0;
        public int stabDefence = 0;
        public int slashDefence = 0;
        public int crushDefence = 0;
        public int rangedDefence = 0;
        public int magicDefence = 0;
    }
}

package com.ethan.combatcalc;

import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Detects equipment set effects that grant accuracy or damage multipliers.
 *
 * ### Sets currently detected
 *
 *   Void Knight (all combat types)
 *     Requires: correct helm for the combat type (melee 11665 / ranger 11664 / mage 11663)
 *     + Void knight top (8839) or Elite void top (13072)
 *     + Void knight robe (8840) or Elite void robe (13073)
 *     + Void knight gloves (8842)
 *     Bonus: +10% accuracy, +10% damage (Elite Void gives +12.5% damage for ranged/magic).
 *     Note: this class applies a uniform +10% for both standard and Elite Void —
 *           the damage difference is an area for future improvement.
 *
 *   Obsidian armour (melee only)
 *     Requires: Obsidian helm (21298) + platebody (21301) + platelegs (21304)
 *               + any obsidian weapon (Toktz-xil-ul 6522, Toktz-xil-ak 6523,
 *                 Toktz-xil-ek 6524, Toktz-mej-tal 6526, Toktz-ket-em 6528).
 *     Bonus: +10% accuracy and +10% damage.
 *
 * ### Usage note
 *   This detector is instantiated and available via Guice injection.  The set-effect
 *   multipliers it returns are intended to be applied by the caller (e.g. in the
 *   combat calculation pipeline) — they are not automatically applied here.
 */
@Singleton
public class EquipmentSynergyDetector
{
    private final Client client;

    @Inject
    public EquipmentSynergyDetector(Client client)
    {
        this.client = client;
    }

    /**
     * Returns the accuracy multiplier granted by any active equipment set bonus.
     * Currently checks Void Knight and Obsidian sets.
     * Returns 1.0 (no bonus) if no set effect is active.
     */
    public double getSetEffectAccuracyMultiplier(CombatType combatType)
    {
        double multiplier = 1.0;

        // Void Knight set: +10% melee/ranged accuracy, +45% magic accuracy.
        if (isWearingVoidSet(combatType))
        {
            multiplier *= combatType == CombatType.MAGIC ? 1.45 : 1.10;
        }

        // Obsidian set: +10% melee accuracy (requires full set)
        if (combatType == CombatType.MELEE && isWearingObsidianSet())
        {
            multiplier *= 1.10;
        }

        return multiplier;
    }

    /**
     * Gets damage multiplier from equipment set effects.
     */
    public double getSetEffectDamageMultiplier(CombatType combatType)
    {
        double multiplier = 1.0;

        // Void Knight damage only applies to melee and ranged.
        if (isWearingVoidSet(combatType))
        {
            if (combatType == CombatType.MELEE)
            {
                multiplier *= 1.10;
            }
            else if (combatType == CombatType.RANGED)
            {
                multiplier *= isWearingEliteVoid() ? 1.125 : 1.10;
            }
        }

        // Obsidian set: +10% damage (requires full set)
        if (combatType == CombatType.MELEE && isWearingObsidianSet())
        {
            multiplier *= 1.10;
        }

        return multiplier;
    }

    /**
     * Checks if wearing full Void Knight set for a specific combat type.
     */
    private boolean isWearingVoidSet(CombatType combatType)
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return false;
        }

        Item helmet = equipment.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
        Item top = equipment.getItem(EquipmentInventorySlot.BODY.getSlotIdx());
        Item legs = equipment.getItem(EquipmentInventorySlot.LEGS.getSlotIdx());
        Item hands = equipment.getItem(EquipmentInventorySlot.GLOVES.getSlotIdx());

        // Check for Void helmet (varies by type)
        if (helmet == null || helmet.getId() == -1)
        {
            return false;
        }

        int helmetId = helmet.getId();
        boolean validHelmet = false;

        switch (combatType)
        {
            case MELEE:
                validHelmet = helmetId == 11665; // Void melee helm
                break;
            case RANGED:
                validHelmet = helmetId == 11664; // Void ranger helm
                break;
            case MAGIC:
                validHelmet = helmetId == 11663; // Void mage helm
                break;
        }

        if (!validHelmet)
        {
            return false;
        }

        // Void knight top (8839) or Elite void top (13072), Void robe/legs (8840) or Elite (13073), Void gloves (8842)
        boolean validTop = top != null && (top.getId() == 8839 || top.getId() == 13072);
        boolean validLegs = legs != null && (legs.getId() == 8840 || legs.getId() == 13073);
        boolean validGloves = hands != null && hands.getId() == 8842;
        return validTop && validLegs && validGloves;
    }

    private boolean isWearingEliteVoid()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return false;
        }

        Item top = equipment.getItem(EquipmentInventorySlot.BODY.getSlotIdx());
        Item legs = equipment.getItem(EquipmentInventorySlot.LEGS.getSlotIdx());
        return top != null && legs != null && top.getId() == 13072 && legs.getId() == 13073;
    }

    /**
     * Checks if wearing full Obsidian set (melee only).
     */
    private boolean isWearingObsidianSet()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return false;
        }

        Item helmet = equipment.getItem(EquipmentInventorySlot.HEAD.getSlotIdx());
        Item top = equipment.getItem(EquipmentInventorySlot.BODY.getSlotIdx());
        Item legs = equipment.getItem(EquipmentInventorySlot.LEGS.getSlotIdx());
        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());

        // Obsidian helm (21298), platebody (21301), platelegs (21304) + any obsidian weapon
        if (helmet == null || top == null || legs == null || weapon == null)
        {
            return false;
        }
        boolean wearingArmour = helmet.getId() == 21298 && top.getId() == 21301 && legs.getId() == 21304;
        // Obsidian weapons: Toktz-xil-ul (6522), Toktz-xil-ak (6523), Toktz-xil-ek (6524),
        //                   Toktz-mej-tal (6526), Toktz-ket-em (6528)
        int wid = weapon.getId();
        boolean wearingObsidianWeapon = wid == 6522 || wid == 6523 || wid == 6524 || wid == 6526 || wid == 6528;
        return wearingArmour && wearingObsidianWeapon;
    }

    /**
     * Gets set effect name if applicable.
     */
    public String getActiveSetEffect()
    {
        // Check all possible set effects and return active one
        if (isWearingObsidianSet())
        {
            return "Obsidian Set (+10% Acc/Dmg)";
        }

        // Would check Void here but depends on combat type

        return null;
    }
}

package com.ethan.combatcalc;

import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;

@Singleton
public class InventoryWeaponCollector
{
    private final Client client;
    private final ItemManager itemManager;

    @Inject
    public InventoryWeaponCollector(Client client, ItemManager itemManager)
    {
        this.client = client;
        this.itemManager = itemManager;
    }

    public List<WeaponInfo> collectCandidates()
    {
        List<WeaponInfo> candidates = new ArrayList<>();
        addEquippedWeapon(candidates);
        addInventoryWeapons(candidates);
        return candidates;
    }

    private void addEquippedWeapon(List<WeaponInfo> candidates)
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return;
        }

        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        WeaponInfo info = buildWeaponInfo(weapon);
        if (info.hasWeapon())
        {
            candidates.add(info);
        }
    }

    private void addInventoryWeapons(List<WeaponInfo> candidates)
    {
        ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
        if (inventory == null)
        {
            return;
        }

        for (Item item : inventory.getItems())
        {
            WeaponInfo info = buildWeaponInfo(item);
            if (info.hasWeapon())
            {
                candidates.add(info);
            }
        }
    }

    private WeaponInfo buildWeaponInfo(Item item)
    {
        if (item == null || item.getId() == -1)
        {
            return WeaponInfo.empty();
        }

        ItemStats itemStats = itemManager.getItemStats(item.getId());
        if (itemStats == null || !itemStats.isEquipable() || itemStats.getEquipment() == null)
        {
            return WeaponInfo.empty();
        }

        ItemEquipmentStats stats = itemStats.getEquipment();
        if (!hasOffensiveStats(stats))
        {
            return WeaponInfo.empty();
        }

        ItemComposition composition = itemManager.getItemComposition(item.getId());
        String name = composition != null ? composition.getName() : "";
        if (name == null || name.isEmpty())
        {
            return WeaponInfo.empty();
        }

        return WeaponInfo.builder(name)
                .attackSpeedTicks(stats.getAspeed())
                .stabAttackBonus(stats.getAstab())
                .slashAttackBonus(stats.getAslash())
                .crushAttackBonus(stats.getAcrush())
                .magicAttackBonus(stats.getAmagic())
                .rangedAttackBonus(stats.getArange())
                .strengthBonus(stats.getStr())
                .rangedStrengthBonus(stats.getRstr())
                .magicDamageBonus(stats.getMdmg())
                .build();
    }

    private boolean hasOffensiveStats(ItemEquipmentStats stats)
    {
        return stats.getAstab() != 0 ||
                stats.getAslash() != 0 ||
                stats.getAcrush() != 0 ||
                stats.getAmagic() != 0 ||
                stats.getArange() != 0 ||
                stats.getStr() != 0 ||
                stats.getRstr() != 0 ||
                stats.getMdmg() != 0 ||
                stats.getAspeed() > 0;
    }
}

