package com.ethan.combatcalc;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.nio.charset.StandardCharsets;

/**
 * Loads and provides NPC defensive combat stats from the bundled JSON database.
 *
 * ### Data source
 *   npc_stats.json is packaged inside the jar under src/main/resources/.
 *   It is loaded once at construction time via getClass().getResourceAsStream().
 *   No file system access is performed — the resource lives entirely inside the jar.
 *
 * ### Lookup
 *   NPCs are keyed by name (exact match first, then case-insensitive fallback).
 *   If a name is not found, an empty NpcCombatProfile is returned so the plugin
 *   degrades gracefully, showing a “⚠ NPC Unknown” warning in the overlay.
 *
 * ### Data model
 *   Each entry deserialises into an NpcCombatProfile which holds:
 *     defenceLevel, magicLevel, stabDefence, slashDefence, crushDefence,
 *     rangedDefence, magicDefence.
 */
@Singleton
public class NpcStatsRepository
{
    private final Gson gson;
    private static final Logger logger = LoggerFactory.getLogger(NpcStatsRepository.class);
    private static final String NPC_STATS_FILE = "/npc_stats.json";

    private Map<String, NpcCombatProfile> npcStats = new HashMap<>();

    @Inject
    public NpcStatsRepository(Gson gson)
    {
        this.gson = gson;
        loadNpcStats();
    }

    private void loadNpcStats()
    {
        InputStream resourceStream = getClass().getResourceAsStream(NPC_STATS_FILE);
        if (resourceStream == null)
        {
            logger.warn("Failed to load NPC stats from jar: resource {} was not found", NPC_STATS_FILE);
            npcStats = new HashMap<>();
            return;
        }

        try (InputStreamReader reader = new InputStreamReader(resourceStream, StandardCharsets.UTF_8))
        {
            Type mapType = new TypeToken<Map<String, NpcCombatProfile>>() {}.getType();
            Map<String, NpcCombatProfile> loadedStats = gson.fromJson(reader, mapType);
            if (loadedStats == null)
            {
                npcStats = new HashMap<>();
                return;
            }

            npcStats = new HashMap<>();
            for (Map.Entry<String, NpcCombatProfile> entry : loadedStats.entrySet())
            {
                npcStats.put(normalizeNpcName(entry.getKey()), entry.getValue());
            }
        }
        catch (Exception e)
        {
            logger.warn("Failed to load NPC stats from jar", e);
            npcStats = new HashMap<>();
        }
    }

    /**
     * Retrieve combat profile for an NPC by name.
     */
    public NpcCombatProfile getNpcProfile(String npcName)
    {
        if (npcName == null || npcName.isEmpty())
        {
            return new NpcCombatProfile();
        }

        NpcCombatProfile profile = npcStats.get(normalizeNpcName(npcName));
        if (profile != null)
        {
            return profile;
        }

        NpcCombatProfile unknownProfile = new NpcCombatProfile(npcName);
        logger.info("NPC profile not found for: {}. Using default stats.", npcName);
        return unknownProfile;
    }

    /**
     * Check if NPC profile exists.
     */
    public boolean hasNpcProfile(String npcName)
    {
        if (npcName == null || npcName.isEmpty())
        {
            return false;
        }

        return npcStats.containsKey(normalizeNpcName(npcName));
    }

    /**
     * Get all loaded NPC profiles.
     */
    public Map<String, NpcCombatProfile> getAllNpcProfiles()
    {
        return new HashMap<>(npcStats);
    }

    private String normalizeNpcName(String npcName)
    {
        return npcName.toLowerCase(Locale.ROOT).trim();
    }
}

package com.ethan.combatcalc;

import net.runelite.api.ItemID;

import javax.inject.Inject;
import javax.inject.Singleton;

@Singleton
public class PoweredStaffMaxHitResolver
{
    @Inject
    public PoweredStaffMaxHitResolver()
    {
    }

    public int resolveBaseMaxHit(int itemId, int magicLevel)
    {
        if (magicLevel <= 0)
        {
            return 0;
        }

        if (isTridentOfTheSeas(itemId))
        {
            return tridentBaseMaxHit(magicLevel, 0);
        }
        if (isTridentOfTheSwamp(itemId))
        {
            return tridentBaseMaxHit(magicLevel, 3);
        }
        if (isSanguinestiStaff(itemId))
        {
            return tridentBaseMaxHit(magicLevel, 4);
        }
        if (isWarpedSceptre(itemId))
        {
            return Math.max(0, (int) Math.floor((8 * magicLevel + 96) / 37.0));
        }
        if (isTumekensShadow(itemId))
        {
            return (int) Math.floor(magicLevel / 3.0 + 1);
        }

        return 0;
    }

    public static boolean isPoweredStaff(int itemId)
    {
        return isTridentOfTheSeas(itemId) ||
                isTridentOfTheSwamp(itemId) ||
                isSanguinestiStaff(itemId) ||
                isWarpedSceptre(itemId) ||
                isTumekensShadow(itemId);
    }

    private static int tridentBaseMaxHit(int magicLevel, int offset)
    {
        int effectiveMagic = Math.max(75, Math.min(123, magicLevel));
        return 20 + offset + (effectiveMagic - 75) / 3;
    }

    private static boolean isTridentOfTheSeas(int itemId)
    {
        return itemId == ItemID.TRIDENT_OF_THE_SEAS ||
                itemId == ItemID.TRIDENT_OF_THE_SEAS_FULL ||
                itemId == ItemID.TRIDENT_OF_THE_SEAS_E ||
                itemId == ItemID.TRIDENT_OF_THE_SEAS_O ||
                itemId == ItemID.TRIDENT_OF_THE_SEAS_FULL_O ||
                itemId == ItemID.TRIDENT_OF_THE_SEAS_E_O;
    }

    private static boolean isTridentOfTheSwamp(int itemId)
    {
        return itemId == ItemID.TRIDENT_OF_THE_SWAMP ||
                itemId == ItemID.TRIDENT_OF_THE_SWAMP_E ||
                itemId == ItemID.TRIDENT_OF_THE_SWAMP_O ||
                itemId == ItemID.TRIDENT_OF_THE_SWAMP_E_O;
    }

    private static boolean isSanguinestiStaff(int itemId)
    {
        return itemId == ItemID.SANGUINESTI_STAFF ||
                itemId == ItemID.HOLY_SANGUINESTI_STAFF;
    }

    private static boolean isWarpedSceptre(int itemId)
    {
        return itemId == ItemID.WARPED_SCEPTRE;
    }

    private static boolean isTumekensShadow(int itemId)
    {
        return itemId == ItemID.TUMEKENS_SHADOW ||
                itemId == ItemID.CORRUPTED_TUMEKENS_SHADOW;
    }
}

package com.ethan.combatcalc;

import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.List;

@Singleton
public class RuneLiteSlayerTaskProvider implements SlayerTaskProvider
{
    private static final int BOSS_TASK_ID = 98;

    private final Client client;

    @Inject
    public RuneLiteSlayerTaskProvider(Client client)
    {
        this.client = client;
    }

    @Override
    public String getTaskName()
    {
        if (client == null || client.getVarpValue(VarPlayerID.SLAYER_COUNT) <= 0)
        {
            return null;
        }

        try
        {
            int taskId = client.getVarpValue(VarPlayerID.SLAYER_TARGET);
            int taskRow = resolveTaskRow(taskId);
            if (taskRow <= 0)
            {
                return null;
            }

            Object[] taskName = client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
            return taskName != null && taskName.length > 0 ? String.valueOf(taskName[0]) : null;
        }
        catch (RuntimeException ex)
        {
            return null;
        }
    }

    private int resolveTaskRow(int taskId)
    {
        if (taskId == BOSS_TASK_ID)
        {
            List<Integer> bossRows = client.getDBRowsByValue(
                    DBTableID.SlayerTaskSublist.ID,
                    DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID,
                    0,
                    client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
            if (bossRows == null || bossRows.isEmpty())
            {
                return -1;
            }

            Object[] taskRow = client.getDBTableField(bossRows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
            return taskRow != null && taskRow.length > 0 && taskRow[0] instanceof Integer ? (Integer) taskRow[0] : -1;
        }

        List<Integer> taskRows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, taskId);
        return taskRows == null || taskRows.isEmpty() ? -1 : taskRows.get(0);
    }
}

