import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

import javax.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.Collections;
import java.util.List;

public class TargetWeaknessOverlay extends Overlay
{
    private static final Color BACKGROUND = new Color(0, 0, 0, 170);
    private static final Color BORDER = new Color(255, 220, 120, 210);
    private static final Color DEFENCE_COLOR = new Color(255, 220, 120);
    private static final Color WEAPON_COLOR = new Color(180, 220, 255);
    private static final Color RECOMMEND_COLOR = new Color(180, 255, 180);
    private static final int PADDING_X = 6;
    private static final int PADDING_Y = 4;
    private static final int LINE_GAP = 2;

    private final WillItLandPlugin plugin;
    private final WillItLandConfig config;
    private final Client client;
    private final NpcStatsRepository npcStatsRepository;
    private final WeaknessAnalyzer weaknessAnalyzer;
    private final InventoryWeaponCollector inventoryWeaponCollector;

    @Inject
    public TargetWeaknessOverlay(WillItLandPlugin plugin,
                                 WillItLandConfig config,
                                 Client client,
                                 NpcStatsRepository npcStatsRepository,
                                 WeaknessAnalyzer weaknessAnalyzer,
                                 InventoryWeaponCollector inventoryWeaponCollector)
    {
        this.plugin = plugin;
        this.config = config;
        this.client = client;
        this.npcStatsRepository = npcStatsRepository;
        this.weaknessAnalyzer = weaknessAnalyzer;
        this.inventoryWeaponCollector = inventoryWeaponCollector;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(OverlayPriority.HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showTargetWeaknessOverlay())
        {
            return null;
        }

        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        List<WeaponInfo> candidates = inventoryWeaponCollector.collectCandidates();
        if (config.showAllNpcWeaknessOverlays())
        {
            for (NPC npc : client.getNpcs())
            {
                if (npc.getName() == null || !npcStatsRepository.hasNpcProfile(npc.getName()))
                {
                    continue;
                }
                renderNpcOverlay(graphics, npc, candidates);
            }
            return null;
        }

        renderNpcOverlay(graphics, plugin.getCurrentTargetNpc(), candidates);
        return null;
    }

    private void renderNpcOverlay(Graphics2D graphics, NPC target, List<WeaponInfo> candidates)
    {
        if (target == null || target.getName() == null)
        {
            return;
        }

        if (config.onlyShowWeaknessInCombat() && !isInvolvedInCombat(target))
        {
            return;
        }

        NpcCombatProfile profile = npcStatsRepository.getNpcProfile(target.getName());
        int combatLevel = resolveCombatLevel(target, profile);
        if (combatLevel < config.weaknessMinimumCombatLevel())
        {
            return;
        }

        WeaknessSummary summary = target == plugin.getCurrentTargetNpc() && plugin.getLatestWeaknessSummary() != null
                ? plugin.getLatestWeaknessSummary()
                : weaknessAnalyzer.analyze(profile, candidates == null ? Collections.emptyList() : candidates);
        if (summary == null)
        {
            return;
        }

        String threatLine = buildThreatLine(target, profile, combatLevel);
        String defenceLine = "DEF " + formatWeakness(summary) + " (" + summary.getDefensiveWeaknessValue() + ")";
        String weaponLine = "WEAP " + formatStyle(summary.getWeaponWeakness()) + " (" + summary.getWeaponWeaknessValue() + ")";
        String recommendLine = summary.hasRecommendation()
                ? "BEST " + abbreviate(summary.getRecommendedWeaponName(), 24) + " [" + formatStyle(summary.getRecommendedWeaponStyle()) + "]"
                : "BEST none in inventory";

        net.runelite.api.Point location = target.getCanvasTextLocation(
                graphics,
                threatLine,
                target.getLogicalHeight() + 55);
        if (location == null)
        {
            return;
        }

        FontMetrics metrics = graphics.getFontMetrics();
        int lineHeight = metrics.getHeight();
        int width = Math.max(metrics.stringWidth(threatLine),
                Math.max(metrics.stringWidth(defenceLine),
                        Math.max(metrics.stringWidth(weaponLine), metrics.stringWidth(recommendLine)))) + PADDING_X * 2;
        int height = lineHeight * 4 + LINE_GAP * 3 + PADDING_Y * 2;
        int x = location.getX() - width / 2;
        int y = location.getY() - height;

        graphics.setColor(BACKGROUND);
        graphics.fillRoundRect(x, y, width, height, 8, 8);
        graphics.setColor(BORDER);
        graphics.drawRoundRect(x, y, width, height, 8, 8);

        int textX = x + PADDING_X;
        int baseline = y + PADDING_Y + metrics.getAscent();
        drawLine(graphics, threatLine, textX, baseline, Color.WHITE);
        drawLine(graphics, defenceLine, textX, baseline + lineHeight + LINE_GAP, DEFENCE_COLOR);
        drawLine(graphics, weaponLine, textX, baseline + (lineHeight + LINE_GAP) * 2, WEAPON_COLOR);
        drawLine(graphics, recommendLine, textX, baseline + (lineHeight + LINE_GAP) * 3, RECOMMEND_COLOR);
    }

    private boolean isInvolvedInCombat(NPC npc)
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
        {
            return false;
        }

        Actor playerTarget = localPlayer.getInteracting();
        Actor npcTarget = npc.getInteracting();
        return playerTarget == npc || npcTarget == localPlayer;
    }

    private String buildThreatLine(NPC npc, NpcCombatProfile profile, int combatLevel)
    {
        StringBuilder line = new StringBuilder(abbreviate(npc.getName(), 20));
        if (combatLevel > 0)
        {
            line.append(" L").append(combatLevel);
        }
        if (profile.getMaxHit() > 0)
        {
            line.append(" MAX ").append(profile.getMaxHit());
        }
        if (profile.isAggressive())
        {
            line.append(" AGG");
        }
        return line.toString();
    }

    private int resolveCombatLevel(NPC npc, NpcCombatProfile profile)
    {
        if (profile.getCombatLevel() > 0)
        {
            return profile.getCombatLevel();
        }

        return Math.max(0, npc.getCombatLevel());
    }

    private String formatWeakness(WeaknessSummary summary)
    {
        String label = summary.getWeaknessLabel();
        if (label == null || label.isEmpty())
        {
            label = formatStyle(summary.getDefensiveWeakness());
        }

        if ("wiki".equals(summary.getWeaknessSource()))
        {
            return label + "/wiki";
        }

        return label;
    }

    private void drawLine(Graphics2D graphics, String text, int x, int y, Color color)
    {
        graphics.setColor(color);
        graphics.drawString(text, x, y);
    }

    private String formatStyle(AttackSubType attackSubType)
    {
        if (attackSubType == null)
        {
            return "Unknown";
        }

        return attackSubType.getDisplayName();
    }

    private String abbreviate(String value, int maxLength)
    {
        if (value == null || value.length() <= maxLength)
        {
            return value;
        }

        return value.substring(0, maxLength - 3) + "...";
    }
}

package com.ethan.combatcalc;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

@Singleton
public class WeaknessAnalyzer
{
    private static final List<AttackSubType> ALL_DEFENCE_TYPES = Arrays.asList(
            AttackSubType.STAB,
            AttackSubType.SLASH,
            AttackSubType.CRUSH,
            AttackSubType.RANGED,
            AttackSubType.MAGIC);
    private static final List<AttackSubType> MELEE_WEAPON_TYPES = Arrays.asList(
            AttackSubType.STAB,
            AttackSubType.SLASH,
            AttackSubType.CRUSH);

    @Inject
    public WeaknessAnalyzer()
    {
    }

    public WeaknessSummary analyze(NpcCombatProfile npcProfile, List<WeaponInfo> candidateWeapons)
    {
        if (npcProfile == null)
        {
            return null;
        }

        List<WeaponInfo> candidates = candidateWeapons == null ? Collections.emptyList() : candidateWeapons;
        AttackSubType derivedDefensiveWeakness = weakestDefence(npcProfile, ALL_DEFENCE_TYPES);
        AttackSubType wikiWeakness = mapWikiWeakness(npcProfile.getWikiWeakness());
        AttackSubType defensiveWeakness = wikiWeakness != AttackSubType.UNKNOWN ? wikiWeakness : derivedDefensiveWeakness;
        AttackSubType weaponWeakness = weakestDefence(npcProfile, MELEE_WEAPON_TYPES);
        WeaponChoice recommendation = recommendWeapon(candidates, defensiveWeakness);

        if (recommendation == null && defensiveWeakness != weaponWeakness)
        {
            recommendation = recommendWeapon(candidates, weaponWeakness);
        }

        return new WeaknessSummary(
                defensiveWeakness,
                npcProfile.getDefenceBonusForAttackType(defensiveWeakness),
                weaponWeakness,
                npcProfile.getDefenceBonusForAttackType(weaponWeakness),
                recommendation != null ? recommendation.weapon.getWeaponName() : null,
                recommendation != null ? recommendation.style : AttackSubType.UNKNOWN,
                wikiWeakness != AttackSubType.UNKNOWN ? normalizeWeaknessLabel(npcProfile.getWikiWeakness()) : formatStyle(defensiveWeakness),
                wikiWeakness != AttackSubType.UNKNOWN ? "wiki" : "derived");
    }

    private AttackSubType weakestDefence(NpcCombatProfile npcProfile, List<AttackSubType> types)
    {
        AttackSubType weakest = AttackSubType.UNKNOWN;
        int lowest = Integer.MAX_VALUE;

        for (AttackSubType type : types)
        {
            int defence = npcProfile.getDefenceBonusForAttackType(type);
            if (defence < lowest)
            {
                lowest = defence;
                weakest = type;
            }
        }

        return weakest;
    }

    private AttackSubType mapWikiWeakness(String wikiWeakness)
    {
        if (wikiWeakness == null)
        {
            return AttackSubType.UNKNOWN;
        }

        String normalized = normalizeWeaknessLabel(wikiWeakness);
        switch (normalized)
        {
            case "stab":
                return AttackSubType.STAB;
            case "slash":
                return AttackSubType.SLASH;
            case "crush":
                return AttackSubType.CRUSH;
            case "range":
            case "ranged":
                return AttackSubType.RANGED;
            case "magic":
            case "air":
            case "earth":
            case "fire":
            case "water":
                return AttackSubType.MAGIC;
            default:
                return AttackSubType.UNKNOWN;
        }
    }

    private String normalizeWeaknessLabel(String weakness)
    {
        return weakness == null ? "" : weakness.trim().toLowerCase(Locale.ROOT);
    }

    private String formatStyle(AttackSubType attackSubType)
    {
        return attackSubType == null ? "Unknown" : attackSubType.getDisplayName();
    }

    private WeaponChoice recommendWeapon(List<WeaponInfo> candidates, AttackSubType desiredStyle)
    {
        WeaponChoice best = null;

        for (WeaponInfo weapon : candidates)
        {
            if (weapon == null || !weapon.hasWeapon())
            {
                continue;
            }

            int styleScore = scoreForStyle(weapon, desiredStyle);
            if (styleScore <= 0)
            {
                continue;
            }

            WeaponChoice choice = new WeaponChoice(weapon, desiredStyle, styleScore);
            if (best == null || choice.score > best.score)
            {
                best = choice;
            }
        }

        return best;
    }

    private int scoreForStyle(WeaponInfo weapon, AttackSubType style)
    {
        switch (style)
        {
            case STAB:
                return weapon.getStabAttackBonus() + weapon.getStrengthBonus() / 10;
            case SLASH:
                return weapon.getSlashAttackBonus() + weapon.getStrengthBonus() / 10;
            case CRUSH:
                return weapon.getCrushAttackBonus() + weapon.getStrengthBonus() / 10;
            case RANGED:
                return weapon.getRangedAttackBonus() + weapon.getRangedStrengthBonus() / 10;
            case MAGIC:
                return weapon.getMagicAttackBonus() + Math.round(weapon.getMagicDamageBonus() / 2.0f);
            default:
                return 0;
        }
    }

    private static class WeaponChoice
    {
        private final WeaponInfo weapon;
        private final AttackSubType style;
        private final int score;

        private WeaponChoice(WeaponInfo weapon, AttackSubType style, int score)
        {
            this.weapon = weapon;
            this.style = style;
            this.score = score;
        }
    }
}

package com.ethan.combatcalc;

public class WeaknessSummary
{
    private final AttackSubType defensiveWeakness;
    private final int defensiveWeaknessValue;
    private final AttackSubType weaponWeakness;
    private final int weaponWeaknessValue;
    private final String recommendedWeaponName;
    private final AttackSubType recommendedWeaponStyle;
    private final String weaknessLabel;
    private final String weaknessSource;

    public WeaknessSummary(AttackSubType defensiveWeakness,
                           int defensiveWeaknessValue,
                           AttackSubType weaponWeakness,
                           int weaponWeaknessValue,
                           String recommendedWeaponName,
                           AttackSubType recommendedWeaponStyle)
    {
        this(defensiveWeakness,
                defensiveWeaknessValue,
                weaponWeakness,
                weaponWeaknessValue,
                recommendedWeaponName,
                recommendedWeaponStyle,
                formatStyle(defensiveWeakness),
                "derived");
    }

    public WeaknessSummary(AttackSubType defensiveWeakness,
                           int defensiveWeaknessValue,
                           AttackSubType weaponWeakness,
                           int weaponWeaknessValue,
                           String recommendedWeaponName,
                           AttackSubType recommendedWeaponStyle,
                           String weaknessLabel,
                           String weaknessSource)
    {
        this.defensiveWeakness = defensiveWeakness;
        this.defensiveWeaknessValue = defensiveWeaknessValue;
        this.weaponWeakness = weaponWeakness;
        this.weaponWeaknessValue = weaponWeaknessValue;
        this.recommendedWeaponName = recommendedWeaponName;
        this.recommendedWeaponStyle = recommendedWeaponStyle;
        this.weaknessLabel = weaknessLabel;
        this.weaknessSource = weaknessSource;
    }

    public AttackSubType getDefensiveWeakness()
    {
        return defensiveWeakness;
    }

    public int getDefensiveWeaknessValue()
    {
        return defensiveWeaknessValue;
    }

    public AttackSubType getWeaponWeakness()
    {
        return weaponWeakness;
    }

    public int getWeaponWeaknessValue()
    {
        return weaponWeaknessValue;
    }

    public String getRecommendedWeaponName()
    {
        return recommendedWeaponName;
    }

    public AttackSubType getRecommendedWeaponStyle()
    {
        return recommendedWeaponStyle;
    }

    public String getWeaknessLabel()
    {
        return weaknessLabel;
    }

    public String getWeaknessSource()
    {
        return weaknessSource;
    }

    public boolean hasRecommendation()
    {
        return recommendedWeaponName != null && !recommendedWeaponName.isEmpty()
                && recommendedWeaponStyle != null
                && recommendedWeaponStyle != AttackSubType.UNKNOWN;
    }

    private static String formatStyle(AttackSubType attackSubType)
    {
        return attackSubType == null ? "Unknown" : attackSubType.getDisplayName();
    }
}

package com.ethan.combatcalc;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

final class WeaponAttackStyles
{
    private static final Map<String, AttackSubType[]> ATTACK_TYPES;

    static
    {
        Map<String, AttackSubType[]> attackTypes = new HashMap<>();

        put(attackTypes, "2h Sword", AttackSubType.SLASH, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.SLASH);
        put(attackTypes, "Axe", AttackSubType.SLASH, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.SLASH);
        put(attackTypes, "Banner", AttackSubType.STAB, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.STAB);
        put(attackTypes, "Bladed Staff", AttackSubType.STAB, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.MAGIC, AttackSubType.MAGIC);
        put(attackTypes, "Blaster", AttackSubType.UNKNOWN, AttackSubType.UNKNOWN);
        put(attackTypes, "Bludgeon", AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.CRUSH);
        put(attackTypes, "Blunt", AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.CRUSH);
        put(attackTypes, "Bow", AttackSubType.RANGED, AttackSubType.RANGED, AttackSubType.RANGED);
        put(attackTypes, "Bulwark", AttackSubType.CRUSH, AttackSubType.UNKNOWN);
        put(attackTypes, "Chinchompas", AttackSubType.RANGED, AttackSubType.RANGED, AttackSubType.RANGED);
        put(attackTypes, "Chinchompa", AttackSubType.RANGED, AttackSubType.RANGED, AttackSubType.RANGED);
        put(attackTypes, "Claw", AttackSubType.SLASH, AttackSubType.SLASH, AttackSubType.STAB, AttackSubType.SLASH);
        put(attackTypes, "Crossbow", AttackSubType.RANGED, AttackSubType.RANGED, AttackSubType.RANGED);
        put(attackTypes, "Gun", AttackSubType.UNKNOWN, AttackSubType.CRUSH);
        put(attackTypes, "Multi-Style", AttackSubType.STAB, AttackSubType.RANGED, AttackSubType.MAGIC);
        put(attackTypes, "Multi-Melee", AttackSubType.STAB, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.SLASH);
        put(attackTypes, "Partisan", AttackSubType.STAB, AttackSubType.STAB, AttackSubType.CRUSH, AttackSubType.STAB);
        put(attackTypes, "Pickaxe", AttackSubType.STAB, AttackSubType.STAB, AttackSubType.CRUSH, AttackSubType.STAB);
        put(attackTypes, "Polearm", AttackSubType.STAB, AttackSubType.SLASH, AttackSubType.STAB);
        put(attackTypes, "Polestaff", AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.CRUSH);
        put(attackTypes, "Powered Staff", AttackSubType.MAGIC, AttackSubType.MAGIC, AttackSubType.MAGIC);
        put(attackTypes, "Powered Wand", AttackSubType.MAGIC, AttackSubType.MAGIC, AttackSubType.MAGIC);
        put(attackTypes, "Salamander", AttackSubType.SLASH, AttackSubType.RANGED, AttackSubType.MAGIC);
        put(attackTypes, "Scythe", AttackSubType.SLASH, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.SLASH);
        put(attackTypes, "Slash Sword", AttackSubType.SLASH, AttackSubType.SLASH, AttackSubType.STAB, AttackSubType.SLASH);
        put(attackTypes, "Spear", AttackSubType.STAB, AttackSubType.SLASH, AttackSubType.CRUSH, AttackSubType.STAB);
        put(attackTypes, "Spiked", AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.STAB, AttackSubType.CRUSH);
        put(attackTypes, "Stab Sword", AttackSubType.STAB, AttackSubType.STAB, AttackSubType.SLASH, AttackSubType.STAB);
        put(attackTypes, "Staff", AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.MAGIC, AttackSubType.MAGIC);
        put(attackTypes, "Thrown", AttackSubType.RANGED, AttackSubType.RANGED, AttackSubType.RANGED);
        put(attackTypes, "Unarmed", AttackSubType.CRUSH, AttackSubType.CRUSH, AttackSubType.CRUSH);
        put(attackTypes, "Whip", AttackSubType.SLASH, AttackSubType.SLASH, AttackSubType.SLASH);

        ATTACK_TYPES = Collections.unmodifiableMap(attackTypes);
    }

    private WeaponAttackStyles()
    {
    }

    static boolean hasCategory(String category)
    {
        return ATTACK_TYPES.containsKey(normalizeCategory(category));
    }

    static AttackSubType resolveAttackSubType(String category, int styleIndex)
    {
        AttackSubType[] styles = ATTACK_TYPES.get(normalizeCategory(category));
        if (styles == null || styleIndex < 0 || styleIndex >= styles.length)
        {
            return AttackSubType.UNKNOWN;
        }

        return styles[styleIndex];
    }

    static CombatType combatTypeFor(AttackSubType attackSubType)
    {
        switch (attackSubType)
        {
            case RANGED:
                return CombatType.RANGED;
            case MAGIC:
                return CombatType.MAGIC;
            case STAB:
            case SLASH:
            case CRUSH:
                return CombatType.MELEE;
            default:
                return CombatType.UNKNOWN;
        }
    }

    private static void put(Map<String, AttackSubType[]> attackTypes, String category, AttackSubType... styles)
    {
        attackTypes.put(normalizeCategory(category), styles);
    }

    private static String normalizeCategory(String category)
    {
        if (category == null)
        {
            return "";
        }

        return category
                .replaceAll("<[^>]+>", "")
                .replace('\u00a0', ' ')
                .trim()
                .replaceFirst("(?i)^(weapon|category)\\s*:\\s*", "")
                .replaceAll("\\s+", " ")
                .toLowerCase();
    }
}

package com.ethan.combatcalc;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class WeaponInfo
{
    private final String weaponName;
    private final String ammoName;
    private final int attackSpeedTicks;
    private final int rapidAttackSpeedTicks;
    private final int baseRange;
    private final int longRange;
    private final int stabAttackBonus;
    private final int slashAttackBonus;
    private final int crushAttackBonus;
    private final int magicAttackBonus;
    private final int rangedAttackBonus;
    private final int strengthBonus;
    private final int rangedStrengthBonus;
    private final float magicDamageBonus;
    private final int specialEnergyPercent;
    private final AttackSubType activeAttackSubType;
    private final int activeAttackStyleIndex;
    private final WeaponSpecialAttack specialAttack;
    private final List<String> passiveEffects;
    private final List<String> notes;

    private WeaponInfo(Builder builder)
    {
        this.weaponName = builder.weaponName;
        this.ammoName = builder.ammoName;
        this.attackSpeedTicks = builder.attackSpeedTicks;
        this.rapidAttackSpeedTicks = builder.rapidAttackSpeedTicks;
        this.baseRange = builder.baseRange;
        this.longRange = builder.longRange;
        this.stabAttackBonus = builder.stabAttackBonus;
        this.slashAttackBonus = builder.slashAttackBonus;
        this.crushAttackBonus = builder.crushAttackBonus;
        this.magicAttackBonus = builder.magicAttackBonus;
        this.rangedAttackBonus = builder.rangedAttackBonus;
        this.strengthBonus = builder.strengthBonus;
        this.rangedStrengthBonus = builder.rangedStrengthBonus;
        this.magicDamageBonus = builder.magicDamageBonus;
        this.specialEnergyPercent = builder.specialEnergyPercent;
        this.activeAttackSubType = builder.activeAttackSubType;
        this.activeAttackStyleIndex = builder.activeAttackStyleIndex;
        this.specialAttack = builder.specialAttack;
        this.passiveEffects = Collections.unmodifiableList(new ArrayList<>(builder.passiveEffects));
        this.notes = Collections.unmodifiableList(new ArrayList<>(builder.notes));
    }

    public static Builder builder(String weaponName)
    {
        return new Builder(weaponName);
    }

    public static WeaponInfo empty()
    {
        return builder("").build();
    }

    public Builder toBuilder()
    {
        return new Builder(weaponName)
                .ammoName(ammoName)
                .attackSpeedTicks(attackSpeedTicks)
                .rapidAttackSpeedTicks(rapidAttackSpeedTicks)
                .baseRange(baseRange)
                .longRange(longRange)
                .stabAttackBonus(stabAttackBonus)
                .slashAttackBonus(slashAttackBonus)
                .crushAttackBonus(crushAttackBonus)
                .magicAttackBonus(magicAttackBonus)
                .rangedAttackBonus(rangedAttackBonus)
                .strengthBonus(strengthBonus)
                .rangedStrengthBonus(rangedStrengthBonus)
                .magicDamageBonus(magicDamageBonus)
                .specialEnergyPercent(specialEnergyPercent)
                .activeAttackSubType(activeAttackSubType)
                .activeAttackStyleIndex(activeAttackStyleIndex)
                .specialAttack(specialAttack)
                .passiveEffects(passiveEffects)
                .notes(notes);
    }

    public boolean hasWeapon()
    {
        return weaponName != null && !weaponName.isEmpty();
    }

    public boolean hasAmmo()
    {
        return ammoName != null && !ammoName.isEmpty();
    }

    public boolean hasSpecialAttack()
    {
        return specialAttack != null;
    }

    public String formatAttackSpeed()
    {
        int selectedSpeed = getSelectedAttackSpeedTicks();
        if (selectedSpeed <= 0)
        {
            return "";
        }

        if (selectedSpeed != attackSpeedTicks && attackSpeedTicks > 0)
        {
            return formatTicks(selectedSpeed) + " selected, " + attackSpeedTicks + " base";
        }

        String formatted = formatTicks(selectedSpeed);
        if (rapidAttackSpeedTicks > 0 && rapidAttackSpeedTicks != attackSpeedTicks)
        {
            formatted += ", " + rapidAttackSpeedTicks + " rapid";
        }
        return formatted;
    }

    public String formatRange()
    {
        if (baseRange <= 0)
        {
            return "";
        }

        if (longRange <= 0 || longRange == baseRange)
        {
            return baseRange + " tiles";
        }

        return baseRange + " tiles, " + longRange + " long";
    }

    public String formatActiveStyleSummary()
    {
        if (activeAttackSubType != AttackSubType.RANGED)
        {
            return "";
        }

        switch (activeAttackStyleIndex)
        {
            case 0:
                return "Accurate: +3 Ranged";
            case 1:
                return "Rapid: faster attack speed";
            case 2:
                return "Longrange: +3 Defence, extended range";
            default:
                return "";
        }
    }

    public String formatShiftTooltip()
    {
        if (!hasWeapon())
        {
            return "";
        }

        StringBuilder tooltip = new StringBuilder(weaponName);
        appendTooltipLine(tooltip, "Mode", formatActiveStyleSummary());
        appendTooltipLine(tooltip, "Bonuses", formatRelevantBonuses());
        appendTooltipLine(tooltip, "Speed", formatAttackSpeed());
        appendTooltipLine(tooltip, "Range", formatRange());
        if (hasAmmo())
        {
            appendTooltipLine(tooltip, "Ammo", ammoName);
        }
        if (hasSpecialAttack())
        {
            appendTooltipLine(tooltip, "Spec", specialAttack.formatSummary());
            appendTooltipLine(tooltip, "", specialAttack.getDescription());
        }
        for (String passiveEffect : passiveEffects)
        {
            appendTooltipLine(tooltip, "Effect", passiveEffect);
        }
        for (String note : notes)
        {
            appendTooltipLine(tooltip, "Note", note);
        }

        return tooltip.toString();
    }

    private static void appendTooltipLine(StringBuilder tooltip, String label, String value)
    {
        if (value == null || value.isEmpty())
        {
            return;
        }

        tooltip.append("<br>");
        if (label != null && !label.isEmpty())
        {
            tooltip.append(label).append(": ");
        }
        tooltip.append(value);
    }

    public String formatRelevantBonuses()
    {
        if (activeAttackSubType == AttackSubType.MAGIC)
        {
            String bonus = formatSigned(magicAttackBonus) + " Magic";
            if (magicDamageBonus != 0)
            {
                bonus += ", " + formatMagicDamage();
            }
            return bonus;
        }

        if (activeAttackSubType == AttackSubType.RANGED || rangedStrengthBonus != 0)
        {
            if (activeAttackSubType == AttackSubType.RANGED)
            {
                return formatSigned(rangedAttackBonus) + " Ranged, " + formatSigned(rangedStrengthBonus) + " Ranged Str";
            }
            return formatSigned(rangedStrengthBonus) + " Ranged Str";
        }

        switch (activeAttackSubType)
        {
            case STAB:
                return formatSigned(stabAttackBonus) + " Stab, " + formatSigned(strengthBonus) + " Str";
            case SLASH:
                return formatSigned(slashAttackBonus) + " Slash, " + formatSigned(strengthBonus) + " Str";
            case CRUSH:
                return formatSigned(crushAttackBonus) + " Crush, " + formatSigned(strengthBonus) + " Str";
            default:
                return "";
        }
    }

    public String formatAllOffensiveBonuses()
    {
        return "Stab " + formatSigned(stabAttackBonus)
                + " | Slash " + formatSigned(slashAttackBonus)
                + " | Crush " + formatSigned(crushAttackBonus)
                + " | Magic " + formatSigned(magicAttackBonus)
                + " | Ranged " + formatSigned(rangedAttackBonus);
    }

    public String formatMagicDamage()
    {
        if (magicDamageBonus == (int) magicDamageBonus)
        {
            return formatSigned((int) magicDamageBonus) + "% Magic Dmg";
        }
        return (magicDamageBonus > 0 ? "+" : "") + String.format("%.1f", magicDamageBonus) + "% Magic Dmg";
    }

    private static String formatTicks(int ticks)
    {
        return ticks + " ticks (" + String.format("%.1f", ticks * 0.6) + "s)";
    }

    private static String formatSigned(int value)
    {
        return value > 0 ? "+" + value : String.valueOf(value);
    }

    public String getWeaponName()
    {
        return weaponName;
    }

