package com.ethan.combatcalc;

import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import java.awt.Color;

import javax.inject.Inject;
import java.awt.Dimension;
import java.awt.Graphics2D;

/**
 * Draws the in-game overlay panel.
 *
 * The overlay is registered/deregistered by WillItLandPlugin on startup/shutdown.
 * On every frame, render() pulls the latest CombatResult from the plugin and builds
 * a list of text rows to display.
 *
 * Each row is guarded by a config toggle so the player can choose exactly what
 * information they want to see (attack style, hit chance, max hit, DPS, NPC warning,
 * and a debug breakdown).
 *
 * No game state is read here — all data comes from the pre-computed CombatResult.
 */
public class WillItLandOverlay extends OverlayPanel
{
    private final WillItLandPlugin plugin;
    private final WillItLandConfig config;
    private final TooltipManager tooltipManager;

    @Inject
    public WillItLandOverlay(WillItLandPlugin plugin, WillItLandConfig config, TooltipManager tooltipManager)
    {
        this.plugin = plugin;
        this.config = config;
        this.tooltipManager = tooltipManager;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(OverlayPriority.MED);
    }

    public WillItLandOverlay(WillItLandPlugin plugin, WillItLandConfig config)
    {
        this(plugin, config, null);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        CombatResult result = plugin.getLatestResult();

        // If no valid combat type is set the player has no active NPC target — render nothing.
        if (result.getCombatType() == null || result.getCombatType() == CombatType.UNKNOWN)
        {
            return super.render(graphics);
        }

        // Set a semi-transparent background
        panelComponent.setBackgroundColor(new Color(0, 0, 0, 150)); // Semi-transparent black

        // Header with emoji/icon
        String headerIcon = getAttackStyleIcon(result.getAttackSubType());
        panelComponent.getChildren().add(LineComponent.builder()
                .left(headerIcon + " Will It Land?")
                .leftColor(Color.CYAN)
                .build());

        // Attack style line
        if (config.showAttackStyle())
        {
            String attackStyle = result.getAttackSubType() != null ? result.getAttackSubType().getDisplayName() : "Unknown";
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Style")
                    .right(attackStyle)
                    .rightColor(getStyleColor(result.getAttackSubType()))
                    .build());
        }

        // Hit chance with color coding
        if (config.showHitChance())
        {
            double hitChance = result.getHitChance();
            String hitChanceFormatted = result.formatHitChance();
            Color hitChanceColor = getHitChanceColor(hitChance);

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Hit Chance")
                    .right(hitChanceFormatted)
                    .rightColor(hitChanceColor)
                    .build());
        }

        // Max hit
        if (config.showMaxHit() && result.getMaxHit() > 0)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Max Hit")
                    .right(String.valueOf(result.getMaxHit()))
                    .rightColor(new Color(255, 200, 0)) // Gold
                    .build());
        }

        // DPS
        if (config.showDPS() && result.getMaxHit() > 0)
        {
            double dps = result.getEstimatedDps();
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("DPS (est)")
                    .right(String.format("%.2f", dps))
                    .rightColor(new Color(150, 200, 255)) // Light blue
                    .build());
        }

        if (config.showWeaponIntel())
        {
            renderWeaponIntel(result.getWeaponInfo());
        }

        if (config.showNpcThreatIntel())
        {
            renderNpcThreatIntel(plugin.getLatestNpcProfile(), plugin.getLatestWeaknessSummary());
        }

        // Show warning if NPC stats were not found
        if (config.showNpcWarning() && result.isNpcUnknown())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("⚠ NPC Unknown")
                    .leftColor(new Color(255, 165, 0)) // Orange
                    .build());
        }

        // Show debug info if enabled
        if (result.isDebugMode() && result.getDebugInfo() != null && !result.getDebugInfo().isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("")
                    .build());
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("--- Debug Info ---")
                    .leftColor(new Color(100, 100, 255)) // Light blue
                    .build());

            String[] debugLines = result.getDebugInfo().split("\n");
            for (String line : debugLines)
            {
                if (!line.isEmpty())
                {

                    panelComponent.getChildren().add(LineComponent.builder()
                            .left(line)
                            .leftColor(new Color(200, 200, 200)) // Gray
                            .build());
                }
            }
        }

        return super.render(graphics);
    }

    private void renderWeaponIntel(WeaponInfo weaponInfo)
    {
        if (weaponInfo == null || !weaponInfo.hasWeapon())
        {
            return;
        }

        if (plugin != null && plugin.isShiftDown() && tooltipManager != null)
        {
            String tooltip = weaponInfo.formatShiftTooltip();
            if (!tooltip.isEmpty())
            {
                tooltipManager.add(new Tooltip(tooltip));
            }
        }

        panelComponent.getChildren().add(LineComponent.builder()
                .left("")
                .build());
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Weapon")
                .right(weaponInfo.getWeaponName())
                .rightColor(new Color(255, 220, 120))
                .build());

        String relevantBonuses = weaponInfo.formatRelevantBonuses();
        if (!relevantBonuses.isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Bonuses")
                    .right(relevantBonuses)
                    .rightColor(new Color(220, 220, 220))
                    .build());
        }

        String activeStyle = weaponInfo.formatActiveStyleSummary();
        if (!activeStyle.isEmpty())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Mode")
                    .right(activeStyle)
                    .rightColor(new Color(180, 220, 255))
                    .build());
        }

        if (config.showWeaponSpeed())
        {
            String speed = weaponInfo.formatAttackSpeed();
            if (!speed.isEmpty())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Speed")
                        .right(speed)
                        .rightColor(new Color(180, 220, 255))
                        .build());
            }
        }

        if (config.showWeaponRange())
        {
            String range = weaponInfo.formatRange();
            if (!range.isEmpty())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Range")
                        .right(range)
                        .rightColor(new Color(180, 255, 180))
                        .build());
            }
        }

        if (config.showWeaponAmmo() && weaponInfo.hasAmmo())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Ammo")
                    .right(weaponInfo.getAmmoName())
                    .rightColor(new Color(200, 255, 200))
                    .build());
        }

        if (config.showWeaponSpecialAttack() && weaponInfo.hasSpecialAttack())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Spec")
                    .right(weaponInfo.getSpecialAttack().formatSummary())
                    .rightColor(new Color(255, 180, 180))
                    .build());
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Energy")
                    .right(weaponInfo.getSpecialEnergyPercent() + "%")
                    .rightColor(new Color(255, 220, 160))
                    .build());
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Spec note")
                    .right(weaponInfo.getSpecialAttack().getDescription())
                    .rightColor(new Color(220, 220, 220))
                    .build());
        }

        if (config.showWeaponPassiveEffects())
        {
            for (String passiveEffect : weaponInfo.getPassiveEffects())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Effect")
                        .right(passiveEffect)
                        .rightColor(new Color(220, 220, 220))
                        .build());
            }
            for (String note : weaponInfo.getNotes())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Note")
                        .right(note)
                        .rightColor(new Color(220, 220, 220))
                        .build());
            }
        }

        if (config.showWeaponRawBonuses())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Raw atk")
                    .right(weaponInfo.formatAllOffensiveBonuses())
                    .rightColor(new Color(190, 190, 190))
                    .build());
        }
    }

    private void renderNpcThreatIntel(NpcCombatProfile profile, WeaknessSummary summary)
    {
        if (profile == null && summary == null)
        {
            return;
        }

        panelComponent.getChildren().add(LineComponent.builder()
                .left("")
                .build());

        if (profile != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("NPC")
                    .right(profile.getNpcName() == null ? "Unknown" : profile.getNpcName())
                    .rightColor(new Color(255, 220, 120))
                    .build());

            if (profile.getCombatLevel() > 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("NPC level")
                        .right(String.valueOf(profile.getCombatLevel()))
                        .rightColor(new Color(220, 220, 220))
                        .build());
            }

            if (profile.getMaxHit() > 0)
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("NPC max")
                        .right(String.valueOf(profile.getMaxHit()))
                        .rightColor(new Color(255, 180, 180))
                        .build());
            }

            if (profile.isAggressive())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Aggressive")
                        .right("yes")
                        .rightColor(new Color(255, 180, 120))
                        .build());
            }
        }

        if (summary != null)
        {
            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Weakness")
                    .right(formatWeakness(summary))
                    .rightColor(new Color(255, 220, 120))
                    .build());

            panelComponent.getChildren().add(LineComponent.builder()
                    .left("Weapon weak")
                    .right(summary.getWeaponWeakness().getDisplayName())
                    .rightColor(new Color(180, 220, 255))
                    .build());

            if (summary.hasRecommendation())
            {
                panelComponent.getChildren().add(LineComponent.builder()
                        .left("Best inv")
                        .right(summary.getRecommendedWeaponName())
                        .rightColor(new Color(180, 255, 180))
                        .build());
            }
        }
    }

    private String formatWeakness(WeaknessSummary summary)
    {
        String label = summary.getWeaknessLabel();
        if (label == null || label.isEmpty())
        {
            label = summary.getDefensiveWeakness().getDisplayName();
        }
        return label + " (" + summary.getWeaknessSource() + ")";
    }



    /**
     * Get a display icon for the attack style.
     */
    private String getAttackStyleIcon(AttackSubType attackSubType)
    {
        if (attackSubType == null)
        {
            return "⚔";
        }
        switch (attackSubType)
        {
            case STAB:
                return "🗡";
            case SLASH:
                return "⚔";
            case CRUSH:
                return "🔨";
            case RANGED:
                return "🏹";
            case MAGIC:
                return "✨";
            default:
                return "⚔";
        }
    }

    /**
     * Get color for attack style text.
     */
    private Color getStyleColor(AttackSubType attackSubType)
    {
        if (attackSubType == null)
        {
            return Color.WHITE;
        }
        switch (attackSubType)
        {
            case STAB:
                return new Color(200, 200, 255); // Light blue
            case SLASH:
                return new Color(255, 200, 100); // Orange
            case CRUSH:
                return new Color(255, 150, 150); // Light red
            case RANGED:
                return new Color(150, 255, 150); // Light green
            case MAGIC:
                return new Color(255, 150, 255); // Light magenta
            default:
                return Color.WHITE;
        }
    }

    /**
     * Get color for hit chance based on the percentage.
     * Green (high chance) -> Yellow (medium) -> Red (low chance)
     */
    private Color getHitChanceColor(double hitChance)
    {
        double highThreshold = config.colorHighAccuracy() / 100.0;
        double mediumThreshold = config.colorMediumAccuracy() / 100.0;
        double lowThreshold = config.colorLowAccuracy() / 100.0;

        if (hitChance >= highThreshold)
        {
            return new Color(0, 255, 0); // Green
        }
        else if (hitChance >= mediumThreshold)
        {
            return new Color(255, 255, 0); // Yellow
        }
        else if (hitChance >= lowThreshold)
        {
            return new Color(255, 165, 0); // Orange
        }
        else
        {
            return new Color(255, 0, 0); // Red
        }
    }
}

package com.ethan.combatcalc;

import com.google.inject.Provides;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.config.ConfigManager;
import net.runelite.api.events.GameTick;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.awt.event.KeyEvent;

@PluginDescriptor(
    name = "Will It Land",
        description = "Combat accuracy calculator - shows hit chance % vs your target NPC",
        tags = {"combat", "accuracy", "overlay", "pvm"}
)
/**
 * Main plugin class for Will It Land.
 *
 * What this plugin does:
 *   - On every game tick, checks whether the local player is currently interacting with an NPC.
 *   - If so, it reads the player's current skill levels (already boosted by potions via the API),
 *     their equipped gear bonuses, and the target NPC's defensive stats from the bundled JSON database.
 *   - It then runs the standard OSRS accuracy formula to produce a hit-chance percentage,
 *     a max-hit value, and an estimated DPS figure.
 *   - These values are stored in a CombatResult and picked up by WillItLandOverlay for display.
 *
 * No file I/O is performed at runtime.  NPC stats are loaded once at startup from the
 * bundled npc_stats.json resource inside the jar (see NpcStatsRepository).
 *
 * The plugin only reads game state — it never writes to the game or sends any packets.
 */
public class WillItLandPlugin extends Plugin implements KeyListener
{
    private static final int SPELL_WIND_STRIKE = 3273;
    private static final int SPELL_WATER_STRIKE = 3275;
    private static final int SPELL_EARTH_STRIKE = 3277;
    private static final int SPELL_FIRE_STRIKE = 3279;
    private static final int SPELL_WIND_BOLT = 3281;
    private static final int SPELL_WATER_BOLT = 3283;
    private static final int SPELL_EARTH_BOLT = 3285;
    private static final int SPELL_FIRE_BOLT = 3291;
    private static final int SPELL_WIND_BLAST = 3293;
    private static final int SPELL_WATER_BLAST = 3295;
    private static final int SPELL_EARTH_BLAST = 3297;
    private static final int SPELL_FIRE_BLAST = 3299;
    private static final int SPELL_WIND_WAVE = 3301;
    private static final int SPELL_WATER_WAVE = 3303;
    private static final int SPELL_EARTH_WAVE = 3305;
    private static final int SPELL_FIRE_WAVE = 3307;
    private static final int SPELL_WIND_SURGE = 3309;
    private static final int SPELL_WATER_SURGE = 3311;
    private static final int SPELL_EARTH_SURGE = 3313;
    private static final int SPELL_FIRE_SURGE = 3315;

    @Inject
    private Client client;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private KeyManager keyManager;

    @Inject
    private WillItLandOverlay overlay;

    @Inject
    private TargetWeaknessOverlay targetWeaknessOverlay;

    @Inject
    private WillItLandConfig config;

    @Inject
    private AttackStyleResolver attackStyleResolver;

    @Inject
    private EquipmentStatCollector equipmentCollector;

    @Inject
    private CombatCalculator combatCalculator;

    @Inject
    private CombatModifier combatModifier;

    @Inject
    private WeaponInfoCollector weaponInfoCollector;

    @Inject
    private NpcStatsRepository npcStatsRepository;

    @Inject
    private InventoryWeaponCollector inventoryWeaponCollector;

    @Inject
    private WeaknessAnalyzer weaknessAnalyzer;

    @Inject
    private PoweredStaffMaxHitResolver poweredStaffMaxHitResolver;

    private CombatResult latestResult = new CombatResult();
    private NPC currentTargetNpc;
    private NpcCombatProfile latestNpcProfile;
    private WeaknessSummary latestWeaknessSummary;
    private boolean shiftDown;

    public CombatResult getLatestResult()
    {
        return latestResult;
    }

    public WillItLandConfig getConfig()
    {
        return config;
    }

    public NPC getCurrentTargetNpc()
    {
        return currentTargetNpc;
    }

    public WeaknessSummary getLatestWeaknessSummary()
    {
        return latestWeaknessSummary;
    }

    public NpcCombatProfile getLatestNpcProfile()
    {
        return latestNpcProfile;
    }

    public boolean isShiftDown()
    {
        return shiftDown;
    }

    @Provides
    WillItLandConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(WillItLandConfig.class);
    }

    @Override
    protected void startUp()
    {
        // Register the overlay so it is drawn on screen.
        overlayManager.add(overlay);
        overlayManager.add(targetWeaknessOverlay);
        keyManager.registerKeyListener(this);
    }

    @Override
    protected void shutDown()
    {
        // Remove the overlay and reset state so nothing lingers after the plugin is disabled.
        overlayManager.remove(overlay);
        overlayManager.remove(targetWeaknessOverlay);
        keyManager.unregisterKeyListener(this);
        latestResult = new CombatResult();
        currentTargetNpc = null;
        latestNpcProfile = null;
        latestWeaknessSummary = null;
        shiftDown = false;
    }

    @Override
    public void keyTyped(KeyEvent e)
    {
    }

    @Override
    public void keyPressed(KeyEvent e)
    {
        if (e.getKeyCode() == KeyEvent.VK_SHIFT)
        {
            shiftDown = true;
        }
    }

    @Override
    public void keyReleased(KeyEvent e)
    {
        if (e.getKeyCode() == KeyEvent.VK_SHIFT)
        {
            shiftDown = false;
        }
    }

    @Override
    public void focusLost()
    {
        shiftDown = false;
    }

    /**
     * Runs once per game tick (~600 ms).
     *
     * Flow:
     *   1. Bail out if no local player exists (e.g. loading screen).
     *   2. Check who the player is currently interacting with.  If it is not an NPC
     *      (e.g. another player, or nobody), clear the result and return — the overlay
     *      will show nothing.
     *   3. Determine what combat style is currently selected (melee/ranged/magic) and
     *      which sub-type (stab/slash/crush).
     *   4. Build a CombatProfile for the player using current boosted levels + gear.
     *   5. Look up the target NPC's defensive stats from the JSON database.
     *   6. Run the appropriate accuracy calculation and store the result.
     *   7. Optionally populate debug breakdown lines if debug mode is on in config.
     */
    @Subscribe
    public void onGameTick(GameTick event)
    {
        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null)
        {
            return;
        }

        // Get target
        Actor interacting = localPlayer.getInteracting();
        NPC targetNpc = null;
        if (interacting instanceof NPC)
        {
            targetNpc = (NPC) interacting;
        }

        if (targetNpc == null)
        {
            latestResult = new CombatResult();
            currentTargetNpc = null;
            latestNpcProfile = null;
            latestWeaknessSummary = null;
            return;
        }

        currentTargetNpc = targetNpc;

        // Resolve combat type and subtype
        CombatType combatType = attackStyleResolver.resolveCombatType(client);
        AttackSubType attackSubType = attackStyleResolver.resolveAttackSubType(client, combatType);

        // Build player combat profile
        CombatProfile playerProfile = buildPlayerProfile(combatType, attackSubType);
        applyAttackStyleBonuses(playerProfile, combatType);
        WeaponInfo weaponInfo = weaponInfoCollector.collect(attackSubType);

        // Build NPC combat profile
        NpcCombatProfile npcProfile = npcStatsRepository.getNpcProfile(targetNpc.getName());
        latestNpcProfile = npcProfile;
        latestWeaknessSummary = weaknessAnalyzer.analyze(npcProfile, inventoryWeaponCollector.collectCandidates());

        // Check if NPC was found in database
        boolean npcFound = npcStatsRepository.hasNpcProfile(targetNpc.getName());

        // Calculate based on combat type
        if (combatType == CombatType.MELEE)
        {
            latestResult = combatCalculator.calculateMeleeAccuracy(playerProfile, npcProfile);
        }
        else if (combatType == CombatType.RANGED)
        {
            latestResult = combatCalculator.calculateRangedAccuracy(playerProfile, npcProfile);
        }
        else if (combatType == CombatType.MAGIC)
        {
            latestResult = combatCalculator.calculateMagicAccuracy(playerProfile, npcProfile);
        }

        latestResult.setWeaponInfo(weaponInfo);

        // Set unknown flag if NPC wasn't in database
        if (!npcFound)
        {
            latestResult.setNpcUnknown(true);
        }

        // Add debug info if enabled
        if (config.debugMode())
        {
            StringBuilder debugInfo = new StringBuilder();
            if (config.showOffensiveRoll())
            {
                debugInfo.append("Offensive Roll: ").append(latestResult.getOffensiveRoll()).append("\n");
            }
            if (config.showDefensiveRoll())
            {
                debugInfo.append("Defensive Roll: ").append(latestResult.getDefensiveRoll()).append("\n");
            }
            debugInfo.append("Max Hit: ").append(latestResult.getMaxHit()).append("\n");
            debugInfo.append("DPS (est): ").append(latestResult.getEstimatedDps()).append("\n");
            if (config.showModifiers())
            {
                debugInfo.append("Prayer Acc: ").append(combatModifier.getAccuracyPrayerMultiplier(combatType)).append("x\n");
                debugInfo.append("Damage Mod: ").append(combatModifier.getDamageMultiplier(combatType, npcProfile)).append("x\n");
            }

            latestResult.setDebugMode(true);
            latestResult.setDebugInfo(debugInfo.toString());
        }
        else
        {
            latestResult.setDebugMode(false);
        }
    }

    /**
     * Assembles a CombatProfile representing the player's current offensive stats.
     *
     * Skill levels are read via client.getBoostedSkillLevel(), which already returns
     * the post-potion value — no manual potion detection is needed or performed.
     *
     * Equipment bonuses are summed across all worn slots by EquipmentStatCollector.
     * The attack bonus selected depends on the active sub-type (stab/slash/crush for
     * melee, ranged attack for ranged, magic attack for magic).
     */
    private CombatProfile buildPlayerProfile(CombatType combatType, AttackSubType attackSubType)
    {
        CombatProfile profile = new CombatProfile();
        profile.setCombatType(combatType);
        profile.setAttackSubType(attackSubType);

        // getBoostedSkillLevel() already includes active potion effects
        int attackLevel = client.getBoostedSkillLevel(Skill.ATTACK);
        int rangedLevel = client.getBoostedSkillLevel(Skill.RANGED);
        int magicLevel = client.getBoostedSkillLevel(Skill.MAGIC);
        int strengthLevel = client.getBoostedSkillLevel(Skill.STRENGTH);

        // Collect equipment bonuses
        EquipmentStatCollector.EquipmentBonuses equipment = equipmentCollector.collectBonuses();

        // Set profile based on combat type
        if (combatType == CombatType.MELEE)
        {
            profile.setEffectiveAttackLevel(attackLevel);
            profile.setEffectiveStrengthLevel(strengthLevel);

            // Select appropriate attack bonus based on subtype
            int attackBonus = 0;
            switch (attackSubType)
            {
                case STAB:
                    attackBonus = equipment.stabAttack;
                    break;
                case SLASH:
                    attackBonus = equipment.slashAttack;
                    break;
                case CRUSH:
                    attackBonus = equipment.crushAttack;
                    break;
                default:
                    attackBonus = equipment.stabAttack;
            }
            profile.setAttackBonus(attackBonus);
            profile.setStrengthBonus(equipment.strengthBonus);
        }
        else if (combatType == CombatType.RANGED)
        {
            profile.setEffectiveAttackLevel(rangedLevel);
            profile.setEffectiveStrengthLevel(rangedLevel);
            profile.setAttackBonus(equipment.rangedAttack);
            profile.setRangedStrengthBonus(equipment.rangedStrengthBonus);
        }
        else if (combatType == CombatType.MAGIC)
        {
            profile.setEffectiveAttackLevel(magicLevel);
            profile.setEffectiveStrengthLevel(magicLevel);
            profile.setAttackBonus(equipment.magicAttack);
            profile.setMagicDamageBonus(equipment.magicDamageBonus);
            profile.setMaxHitBase(getSelectedSpellMaxHit());
            profile.setSpellElement(getSelectedSpellElement());
        }

        return profile;
    }

    private void applyAttackStyleBonuses(CombatProfile profile, CombatType combatType)
    {
        int style = client.getVarpValue(VarPlayer.ATTACK_STYLE);

        if (combatType == CombatType.MELEE)
        {
            if (style == 0)
            {
                profile.setAccuracyStyleBonus(3);
            }
            else if (style == 1)
            {
                profile.setStrengthStyleBonus(3);
            }
            else if (style == 3)
            {
                profile.setAccuracyStyleBonus(1);
                profile.setStrengthStyleBonus(1);
            }
            return;
        }

        if (combatType == CombatType.RANGED)
        {
            if (style == 0)
            {
                profile.setAccuracyStyleBonus(3);
            }
        }
    }

    private int getSelectedSpellMaxHit()
    {
        int poweredStaffMaxHit = getPoweredStaffMaxHit();
        if (poweredStaffMaxHit > 0)
        {
            return poweredStaffMaxHit;
        }

        int maxHit = getSpellMaxHit(client.getVarpValue(VarPlayerID.LASTCASTSPELL));
        if (maxHit == 0)
        {
            maxHit = getSpellMaxHit(client.getVarpValue(VarPlayerID.AUTOCAST_SPELL_OBJ));
        }
        if (maxHit == 0)
        {
            maxHit = getSpellMaxHit(client.getVarbitValue(VarbitID.AUTOCAST_SPELL));
        }

        return maxHit;
    }

    private String getSelectedSpellElement()
    {
        if (getPoweredStaffMaxHit() > 0)
        {
            return null;
        }

        String element = getSpellElement(client.getVarpValue(VarPlayerID.LASTCASTSPELL));
        if (element == null)
        {
            element = getSpellElement(client.getVarpValue(VarPlayerID.AUTOCAST_SPELL_OBJ));
        }
        if (element == null)
        {
            element = getSpellElement(client.getVarbitValue(VarbitID.AUTOCAST_SPELL));
        }

        return element;
    }

    private int getPoweredStaffMaxHit()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return 0;
        }

        Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        if (weapon == null || weapon.getId() == -1)
        {
            return 0;
        }

        return poweredStaffMaxHitResolver.resolveBaseMaxHit(
                weapon.getId(),
                client.getBoostedSkillLevel(Skill.MAGIC));
    }

    private int getSpellMaxHit(int spellId)
    {
        switch (spellId)
        {
            case SPELL_WIND_STRIKE:
                return 2;
            case SPELL_WATER_STRIKE:
                return 4;
            case SPELL_EARTH_STRIKE:
                return 6;
            case SPELL_FIRE_STRIKE:
                return 8;
            case SPELL_WIND_BOLT:
                return chaosGauntletsEquipped() ? 12 : 9;
            case SPELL_WATER_BOLT:
                return chaosGauntletsEquipped() ? 13 : 10;
            case SPELL_EARTH_BOLT:
                return chaosGauntletsEquipped() ? 14 : 11;
            case SPELL_FIRE_BOLT:
                return chaosGauntletsEquipped() ? 15 : 12;
            case SPELL_WIND_BLAST:
                return 13;
            case SPELL_WATER_BLAST:
                return 14;
            case SPELL_EARTH_BLAST:
                return 15;
            case SPELL_FIRE_BLAST:
                return 16;
            case SPELL_WIND_WAVE:
                return 17;
            case SPELL_WATER_WAVE:
                return 18;
            case SPELL_EARTH_WAVE:
                return 19;
            case SPELL_FIRE_WAVE:
                return 20;
            case SPELL_WIND_SURGE:
                return 21;
            case SPELL_WATER_SURGE:
                return 22;
            case SPELL_EARTH_SURGE:
                return 23;
            case SPELL_FIRE_SURGE:
                return 24;
            default:
                return 0;
        }
    }

    private String getSpellElement(int spellId)
    {
        switch (spellId)
        {
            case SPELL_WIND_STRIKE:
            case SPELL_WIND_BOLT:
            case SPELL_WIND_BLAST:
            case SPELL_WIND_WAVE:
            case SPELL_WIND_SURGE:
                return "air";
            case SPELL_WATER_STRIKE:
            case SPELL_WATER_BOLT:
            case SPELL_WATER_BLAST:
            case SPELL_WATER_WAVE:
            case SPELL_WATER_SURGE:
                return "water";
            case SPELL_EARTH_STRIKE:
            case SPELL_EARTH_BOLT:
            case SPELL_EARTH_BLAST:
            case SPELL_EARTH_WAVE:
            case SPELL_EARTH_SURGE:
                return "earth";
            case SPELL_FIRE_STRIKE:
            case SPELL_FIRE_BOLT:
            case SPELL_FIRE_BLAST:
            case SPELL_FIRE_WAVE:
            case SPELL_FIRE_SURGE:
                return "fire";
            default:
                return null;
        }
    }

    private boolean chaosGauntletsEquipped()
    {
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment == null)
        {
            return false;
        }

        Item gloves = equipment.getItem(EquipmentInventorySlot.GLOVES.getSlotIdx());
        return gloves != null && gloves.getId() == ItemID.CHAOS_GAUNTLETS;
    }

}

