        assertEquals("Reduces the target's Defence by 30% if it hits.", info.getSpecialAttack().getDescription());
        assertEquals("Crush", info.getSpecialAttack().getDefenceRoll());
    }

    @Test
    public void returnsPassiveEffectForKnownWeapon()
    {
        WeaponIntelDatabase database = new WeaponIntelDatabase();

        WeaponInfo info = database.lookup("Twisted bow");

        assertFalse(info.hasSpecialAttack());
        assertEquals(1, info.getPassiveEffects().size());
        assertEquals("Accuracy and damage scale with the target's Magic level.", info.getPassiveEffects().get(0));
    }

    @Test
    public void normalizesRuneLiteMarkupAndCase()
    {
        WeaponIntelDatabase database = new WeaponIntelDatabase();

        WeaponInfo info = database.lookup("<col=ff981f>toxic blowpipe</col>");

        assertTrue(info.hasSpecialAttack());
        assertEquals("Toxic Siphon", info.getSpecialAttack().getName());
        assertEquals(5, info.getBaseRange());
        assertEquals(7, info.getLongRange());
    }

    @Test
    public void returnsEmptyInfoForUnknownWeapon()
    {
        WeaponIntelDatabase database = new WeaponIntelDatabase();

        WeaponInfo info = database.lookup("Training sword");

        assertEquals("Training sword", info.getWeaponName());
        assertFalse(info.hasSpecialAttack());
        assertTrue(info.getPassiveEffects().isEmpty());
        assertEquals(0, info.getBaseRange());
    }
}

package com.ethan.combatcalc;

import org.junit.Test;

import java.awt.Color;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

import static org.junit.Assert.assertEquals;

public class WillItLandOverlayTest
{
    @Test
    public void dpsUsesCollectedWeaponAttackSpeed()
    {
        CombatResult result = new CombatResult();
        result.setHitChance(1.0);
        result.setMaxHit(10);
        result.setWeaponInfo(WeaponInfo.builder("Test weapon")
                .attackSpeedTicks(5)
                .build());

        assertEquals(1.67, result.getEstimatedDps(), 0.001);
    }

    @Test
    public void dpsUsesSelectedRapidWeaponSpeed()
    {
        CombatResult result = new CombatResult();
        result.setHitChance(1.0);
        result.setMaxHit(10);
        result.setWeaponInfo(WeaponInfo.builder("Dragon knife")
                .attackSpeedTicks(3)
                .rapidAttackSpeedTicks(2)
                .activeAttackStyleIndex(1)
                .build());

        assertEquals(4.17, result.getEstimatedDps(), 0.001);
    }

    @Test
    public void hitChanceColorsUseConfiguredThresholds()
            throws Exception
    {
        WillItLandOverlay overlay = new WillItLandOverlay(null, config(70, 40, 20));

        assertEquals(new Color(0, 255, 0), invokeHitChanceColor(overlay, 0.75));
        assertEquals(new Color(255, 255, 0), invokeHitChanceColor(overlay, 0.45));
        assertEquals(new Color(255, 165, 0), invokeHitChanceColor(overlay, 0.25));
        assertEquals(new Color(255, 0, 0), invokeHitChanceColor(overlay, 0.10));
    }

    private static Color invokeHitChanceColor(WillItLandOverlay overlay, double hitChance)
            throws Exception
    {
        Method method = WillItLandOverlay.class.getDeclaredMethod("getHitChanceColor", double.class);
        method.setAccessible(true);
        return (Color) method.invoke(overlay, hitChance);
    }

    private static WillItLandConfig config(int high, int medium, int low)
    {
        return (WillItLandConfig) Proxy.newProxyInstance(
                WillItLandConfig.class.getClassLoader(),
                new Class<?>[]{WillItLandConfig.class},
                (proxy, method, args) ->
                {
                    if ("colorHighAccuracy".equals(method.getName()))
                    {
                        return high;
                    }
                    if ("colorMediumAccuracy".equals(method.getName()))
                    {
                        return medium;
                    }
                    if ("colorLowAccuracy".equals(method.getName()))
                    {
                        return low;
                    }
                    return method.getDefaultValue() != null ? method.getDefaultValue() : defaultValue(method.getReturnType());
                });
    }

    private static Object defaultValue(Class<?> returnType)
    {
        if (!returnType.isPrimitive())
        {
            return null;
        }
        if (returnType == boolean.class)
        {
            return false;
        }
        if (returnType == int.class)
        {
            return 0;
        }
        if (returnType == double.class)
        {
            return 0.0;
        }
        return 0;
    }
}

package com.ethan.combatcalc;

import com.google.inject.Provides;
import net.runelite.client.config.ConfigManager;
import org.junit.Test;

import java.lang.reflect.Method;

import static org.junit.Assert.assertTrue;

public class WillItLandPluginTest
{
    @Test
    public void providesPluginConfig()
    {
        boolean hasConfigProvider = false;

        for (Method method : WillItLandPlugin.class.getDeclaredMethods())
        {
            boolean providesWillItLandConfig = method.isAnnotationPresent(Provides.class)
                    && method.getReturnType().equals(WillItLandConfig.class);
            boolean acceptsConfigManager = method.getParameterCount() == 1
                    && method.getParameterTypes()[0].equals(ConfigManager.class);

            if (providesWillItLandConfig && acceptsConfigManager)
            {
                hasConfigProvider = true;
                break;
            }
        }

        assertTrue("WillItLandPlugin should provide WillItLandConfig through ConfigManager", hasConfigProvider);
    }
}
